const e = (intuition:Pair, details:[Pair,Pair][], hack:[Pair,Pair,Pair], life:{title:Pair;problem:Pair;steps:Pair[];answer:string;answerText?:Pair;connection:Pair;takeaway:Pair},expression:string,expected:number) => ({
  intuition:b(...intuition), details:details.map(([title,body])=>({title:b(...title),body:b(...body)})),
  hacks:[{title:b(...hack[0]),body:b(...hack[1]),caution:b(...hack[2])}],
  life:{title:b(...life.title),problem:b(...life.problem),steps:s(...life.steps.map(p=>b(...p))),answer:life.answer,...(life.answerText?{answerText:b(...life.answerText)}:{}),connection:b(...life.connection),takeaway:b(...life.takeaway)},checks:[{expression,expected}]
});

export const advancedEnrichment:EnrichmentMap = {
  'angles':e(['Угол показывает, насколько повернулось одно направление относительно другого. Размер лучей на рисунке не меняет величину угла.','Бұрыш бір бағыттың екіншісіне қатысты қанша бұрылғанын көрсетеді. Сәулелердің ұзындығы бұрышты өзгертпейді.'],[
    [['Сначала найди вершину','Алдымен төбені тап'],['Вершина — общая начальная точка двух лучей. При записи ∠ABC вершина B стоит посередине. Не измеряй расстояние между концами лучей: угол измеряется в градусах, а не в сантиметрах.','Төбе — екі сәуленің ортақ бастапқы нүктесі. ∠ABC жазуында B ортасында тұрады. Сәулелер ұштарының арақашықтығын өлшеме: бұрыш сантиметрмен емес, градуспен өлшенеді.']],
    [['Связи важнее картинки','Байланыс суреттен маңызды'],['Смежные углы вместе образуют развёрнутый угол 180°. Вертикальные углы при пересечении двух прямых равны. Если две прямые параллельны, секущая создаёт равные соответственные углы; параллельность нужно знать из условия, а не угадывать по рисунку.','Сыбайлас бұрыштардың қосындысы 180°. Екі түзу қиылысқандағы вертикаль бұрыштар тең. Параллель түзулерді қиюшы қиғанда сәйкес бұрыштар тең болады; параллельдік шартта берілуі тиіс.']]
  ],[['Ищи прямую линию','Түзу сызықты ізде'],['Если два соседних угла заполняют прямую, неизвестный угол равен 180° минус известный. Нарисуй общую сторону и две противоположные стороны.','Екі көршілес бұрыш түзу сызық құраса, белгісіз бұрыш 180°-тан белгілі бұрышты азайтумен табылады. Ортақ және қарама-қарсы қабырғаларды белгіле.'],['Не любые соседние углы смежные: внешние лучи должны быть противоположными.','Кез келген көршілес бұрыш сыбайлас емес: сыртқы сәулелер қарама-қарсы болуы керек.']],{title:['Поворот камеры','Камераны бұру'],problem:['В модели камера смотрит под углом 65° к прямому коридору. Какой угол до противоположного направления коридора?','Модельде камера дәліздің бір бағытына 65° бұрышпен қарап тұр. Қарама-қарсы бағытқа дейінгі бұрыш қандай?'],steps:[['Оба направления коридора образуют 180°.','Дәліздің екі бағыты 180° құрайды.'],['Искомый угол вместе с 65° даёт 180°.','Ізделінді бұрыш пен 65° қосындысы 180°.'],['Вычитаем: 180° − 65° = 115°.','Азайтамыз: 180° − 65° = 115°.']],answer:'115°',connection:['Модель связывает поворот с парой смежных углов.','Модель бұрылуды сыбайлас бұрыштармен байланыстырады.'],takeaway:['Сначала установи геометрическую связь, затем вычисляй.','Алдымен геометриялық байланысты анықта, содан кейін есепте.']},'180-65',115),
  'triangles':e(['Треугольник жёстко связывает три стороны и три угла. Поэтому несколько известных величин часто позволяют восстановить остальные.','Үшбұрыш үш қабырға мен үш бұрышты байланыстырады. Бірнеше белгілі шама қалғандарын табуға мүмкіндік береді.'],[
    [['Отмечай тип треугольника','Үшбұрыш түрін белгіле'],['Равнобедренный треугольник имеет две равные стороны и равные углы напротив них. Прямоугольный содержит угол 90°. Катеты образуют прямой угол, гипотенуза лежит напротив него и является самой длинной стороной.','Теңбүйірлі үшбұрыштың екі қабырғасы және оларға қарсы бұрыштары тең. Тікбұрышты үшбұрышта 90° бұрыш бар. Катеттер тік бұрышты құрайды, гипотенуза оның қарсысында жатады және ең ұзын қабырға болады.']],
    [['Проверяй возможность','Мүмкіндігін тексер'],['Сумма углов любого треугольника равна 180°. Для сторон действует неравенство треугольника: сумма любых двух сторон больше третьей. В прямоугольном треугольнике a² + b² = c²; перед подстановкой выясни, где гипотенуза c.','Кез келген үшбұрыш бұрыштарының қосындысы 180°. Кез келген екі қабырғаның қосындысы үшіншісінен үлкен. Тікбұрышты үшбұрышта a² + b² = c²; алдымен c гипотенузасын анықта.']]
  ],[['Знакомые тройки','Таныс үштіктер'],['Запомни 3–4–5 и кратные этой тройке: 6–8–10, 9–12–15. Это ускоряет проверку прямоугольного треугольника.','3–4–5 және оған еселі 6–8–10, 9–12–15 үштіктерін есте сақта. Олар тікбұрышты үшбұрышты тексеруді жылдамдатады.'],['Равенство квадратов проверяют с самой большой стороной справа.','Квадраттар теңдігінде оң жақта ең үлкен қабырға тұруы керек.']],{title:['Лестница у стены','Қабырғадағы баспалдақ'],problem:['В упрощённой модели лестница длиной 5 м стоит на ровной земле в 3 м от вертикальной стены. На какой высоте её верх?','Қарапайым модельде ұзындығы 5 м баспалдақ тік қабырғадан 3 м қашықта тұр. Жоғарғы ұшының биіктігі қандай?'],steps:[['Стена и земля образуют прямой угол; лестница — гипотенуза.','Қабырға мен жер тік бұрыш құрайды; баспалдақ — гипотенуза.'],['h² = 5² − 3² = 25 − 9 = 16.','h² = 5² − 3² = 25 − 9 = 16.'],['Высота положительна: h = 4 м.','Биіктік оң: h = 4 м.']],answer:'4 м',connection:['Теорема Пифагора переводит расстояния в модель треугольника.','Пифагор теоремасы арақашықтықтарды үшбұрыш моделіне айналдырады.'],takeaway:['Отрицательный корень не описывает длину.','Теріс түбір ұзындықты сипаттамайды.']},'25-9',16),
  'quadrilaterals':e(['Название четырёхугольника сообщает полезные свойства. Не переносим свойства квадрата на любую фигуру с четырьмя сторонами.','Төртбұрыш атауы оның пайдалы қасиеттерін білдіреді. Шаршы қасиеттерін кез келген төрт қабырғалы фигураға қолданбаймыз.'],[
    [['Начни с признаков','Белгілерден баста'],['У параллелограмма противоположные стороны параллельны и равны. У прямоугольника все углы прямые. Ромб имеет четыре равные стороны; квадрат одновременно является ромбом и прямоугольником. Сумма внутренних углов выпуклого четырёхугольника — 360°.','Параллелограмның қарама-қарсы қабырғалары параллель және тең. Тіктөртбұрыштың барлық бұрыштары тік. Ромбтың төрт қабырғасы тең; шаршы — әрі ромб, әрі тіктөртбұрыш. Дөңес төртбұрыш бұрыштарының қосындысы 360°.']],
    [['Основание и высота','Табан мен биіктік'],['Площадь параллелограмма равна основанию, умноженному на перпендикулярную высоту. Наклонная боковая сторона обычно не является высотой. У трапеции площадь равна полусумме параллельных оснований, умноженной на высоту.','Параллелограмм ауданы табан мен оған перпендикуляр биіктіктің көбейтіндісіне тең. Көлбеу бүйір қабырға әдетте биіктік емес. Трапеция ауданы параллель табандарының жарты қосындысы мен биіктіктің көбейтіндісіне тең.']]
  ],[['Разрежь и переставь','Қиып, орнын ауыстыр'],['Мысленно перенеси крайний треугольник параллелограмма к другому краю: получится прямоугольник с теми же основанием и высотой.','Параллелограмм шетіндегі үшбұрышты екінші шетке ойша жылжыт: табаны мен биіктігі бірдей тіктөртбұрыш шығады.'],['Перестановка частей сохраняет площадь, но может менять периметр.','Бөліктерді жылжыту ауданды сақтайды, бірақ периметр өзгеруі мүмкін.']],{title:['Участок в форме трапеции','Трапеция пішінді жер'],problem:['Модель участка — трапеция с параллельными сторонами 8 и 12 м, расстоянием между ними 5 м. Найди площадь.','Жер моделінің параллель қабырғалары 8 және 12 м, арақашықтығы 5 м. Ауданын тап.'],steps:[['Берём основания 8 и 12 м, высоту 5 м.','Табандар 8 және 12 м, биіктік 5 м.'],['Среднее оснований: (8 + 12)/2 = 10 м.','Табандардың ортасы: (8 + 12)/2 = 10 м.'],['S = 10 · 5 = 50 м².','S = 10 · 5 = 50 м².']],answer:'50 м²',connection:['Площадь нужна для расчёта покрытия или посева.','Аудан жабын не егін мөлшерін есептеуге қажет.'],takeaway:['Проверь, что высота перпендикулярна основаниям.','Биіктіктің табандарға перпендикуляр екенін тексер.']},'(8+12)/2*5',50),
  'circles':e(['Окружность — граница, круг — вся область внутри. Радиус связывает центр с границей; диаметр проходит через центр и равен двум радиусам.','Шеңбер — шекара, дөңгелек — оның ішіндегі бүкіл аймақ. Радиус центрді шекарамен қосады; диаметр центр арқылы өтіп, екі радиусқа тең.'],[
    [['Разделяй длину и площадь','Ұзындық пен ауданды ажырат'],['Длина окружности C = 2πr измеряется в метрах или сантиметрах. Площадь круга S = πr² измеряется в квадратных единицах. Если диаметр удвоен, длина удваивается, а площадь увеличивается в четыре раза.','Шеңбер ұзындығы C = 2πr метрмен не сантиметрмен өлшенеді. Дөңгелек ауданы S = πr² квадрат бірліктермен өлшенеді. Диаметр екі есе артса, ұзындық екі есе, аудан төрт есе артады.']],
    [['Доли полного круга','Толық дөңгелектің үлестері'],['Центральный угол α выделяет α/360 часть полного круга. Умножай эту долю на площадь круга для площади сектора и на длину окружности для длины дуги. Угол в этой записи обязательно выражен в градусах.','Центрлік α бұрышы дөңгелектің α/360 бөлігін бөледі. Сектор ауданы үшін осы үлесті дөңгелек ауданына, доға ұзындығы үшін шеңбер ұзындығына көбейт. Бұл жазуда бұрыш градуспен беріледі.']]
  ],[['Сначала радиус','Алдымен радиус'],['Если задан диаметр, сразу запиши r = d/2 рядом с рисунком. Это защищает от самой частой ошибки в площади.','Диаметр берілсе, суретке бірден r = d/2 деп жаз. Бұл аудан есептеудегі жиі қатеден қорғайды.'],['Число π оставляй точно, если округление не требуется.','Дөңгелектеу қажет болмаса, π санын дәл қалдыр.']],{title:['Круглая клумба','Дөңгелек гүлзар'],problem:['Диаметр круглой клумбы 6 м. Четверть её площади выделили под тюльпаны. Сколько это квадратных метров?','Дөңгелек гүлзар диаметрі 6 м. Ауданының төрттен бірі қызғалдаққа бөлінді. Бұл неше квадрат метр?'],steps:[['Радиус равен 6/2 = 3 м.','Радиус 6/2 = 3 м.'],['Площадь всей клумбы: π · 3² = 9π м².','Толық гүлзар ауданы: π · 3² = 9π м².'],['Четверть площади: 9π/4 м².','Ауданның төрттен бірі: 9π/4 м².']],answer:'9π/4 м²',connection:['Доля площади моделирует распределение посадок.','Аудан үлесі өсімдіктерді бөлу моделін береді.'],takeaway:['Делим площадь на четыре, а радиус не меняем.','Ауданды төртке бөлеміз, радиусты өзгертпейміз.']},'9/4',2.25),
  'similarity':e(['Подобные фигуры имеют одинаковую форму, но могут иметь разный размер. Все соответствующие длины меняются в одном отношении.','Ұқсас фигуралардың пішіні бірдей, өлшемі әртүрлі болуы мүмкін. Сәйкес ұзындықтар бір қатынаста өзгереді.'],[
    [['Сопоставь вершины','Төбелерді сәйкестендір'],['Сначала сопоставь равные углы, затем выпиши соответствующие стороны в одинаковом порядке. Коэффициент подобия k — отношение стороны новой фигуры к соответствующей стороне исходной. Нельзя делить случайно выбранные стороны.','Алдымен тең бұрыштарды сәйкестендір, кейін сәйкес қабырғаларды бір ретпен жаз. Ұқсастық коэффициенті k — жаңа фигура қабырғасының бастапқы сәйкес қабырғаға қатынасы. Кездейсоқ қабырғаларды бөлуге болмайды.']],
    [['Длины, площади, объёмы','Ұзындық, аудан, көлем'],['При увеличении длин в k раз площади увеличиваются в k² раз, объёмы подобных тел — в k³ раз. Это разные правила. Для теней подобие требует вертикальных объектов, ровной поверхности и одинакового направления солнечных лучей.','Ұзындық k есе артса, аудан k² есе, ұқсас денелер көлемі k³ есе артады. Бұлар бөлек ережелер. Көлеңкелер үшін нысандар тік, жер тегіс, сәулелер бағыты бірдей болуы керек.']]
  ],[['Пропорция по паре','Жұп арқылы пропорция'],['Записывай высота/тень для обоих объектов. Одинаковые единицы и одинаковый порядок облегчают проверку.','Екі нысанға да биіктік/көлеңке қатынасын жаз. Бірдей бірліктер мен рет тексеруді жеңілдетеді.'],['Без одинакового освещения подобие теней не гарантировано.','Жарық бірдей болмаса, көлеңкелердің ұқсастығына кепіл жоқ.']],{title:['Высота дерева по тени','Көлеңкеден ағаш биіктігі'],problem:['На ровной площадке шест высотой 2 м даёт тень 3 м, дерево — 12 м. В модели лучи параллельны. Найди высоту дерева.','Тегіс жерде биіктігі 2 м сырықтың көлеңкесі 3 м, ағаштікі 12 м. Модельде сәулелер параллель. Ағаш биіктігін тап.'],steps:[['Прямоугольные треугольники подобны по двум углам.','Тікбұрышты үшбұрыштар екі бұрышы бойынша ұқсас.'],['Тень дерева в 12/3 = 4 раза длиннее.','Ағаш көлеңкесі 12/3 = 4 есе ұзын.'],['Высота дерева: 2 · 4 = 8 м.','Ағаш биіктігі: 2 · 4 = 8 м.']],answer:'8 м',connection:['Измеряем недоступную длину через доступные длины.','Қол жетпейтін ұзындықты өлшенетін ұзындықтармен табамыз.'],takeaway:['Обязательно проговори допущения модели.','Модель болжамдарын міндетті түрде ата.']},'2*12/3',8),
  'plane-vectors':e(['Вектор описывает перемещение: насколько и в каком направлении двинуться. Начальная точка может меняться, само перемещение остаётся тем же.','Вектор орын ауыстыруды сипаттайды: қанша және қай бағытта жылжу керек. Бастапқы нүкте өзгерсе де, орын ауыстыру бірдей қалады.'],[
    [['Координаты перемещения','Орын ауыстыру координаталары'],['Для A(x₁;y₁) и B(x₂;y₂) вектор AB имеет координаты (x₂−x₁;y₂−y₁). Первая координата отвечает за горизонтальное движение, вторая — за вертикальное. При сложении векторов складывай соответствующие координаты.','A(x₁;y₁) және B(x₂;y₂) үшін AB векторы (x₂−x₁;y₂−y₁). Бірінші координата көлденең, екіншісі тік қозғалысты береді. Векторларды қосқанда сәйкес координаталарды қос.']],
    [['Маршрут и кратчайший путь','Маршрут пен ең қысқа жол'],['Длина вектора (a;b) равна √(a²+b²). Это прямое расстояние между началом и концом. Длина пройденного маршрута может быть больше. Скалярное произведение a₁b₁+a₂b₂ помогает проверять перпендикулярность: для ненулевых векторов оно равно нулю.','(a;b) векторының ұзындығы √(a²+b²). Бұл бастапқы және соңғы нүктелердің тура арақашықтығы. Маршрут ұзындығы үлкен болуы мүмкін. a₁b₁+a₂b₂ скаляр көбейтіндісі нөл болса, нөлдік емес векторлар перпендикуляр.']]
  ],[['Рисуй стрелку результата','Нәтиже жебесін сал'],['После сложения нарисуй одну стрелку от начальной точки до конечной и проверь знаки координат.','Қосқаннан кейін бастапқыдан соңғы нүктеге бір жебе салып, координата таңбаларын тексер.'],['Не складывай длины, если требуется длина результирующего вектора.','Қорытқы вектор ұзындығы қажет болса, жеке ұзындықтарды қоспа.']],{title:['Доставка на сетке улиц','Көше торындағы жеткізу'],problem:['Курьер прошёл 6 кварталов на восток и 8 на север. Квартал принимаем за единицу. Найди прямое перемещение.','Курьер шығысқа 6, солтүстікке 8 квартал жүрді. Кварталды бірлік деп аламыз. Тура орын ауыстыруды тап.'],steps:[['Вектор перемещения (6;8).','Орын ауыстыру векторы (6;8).'],['Квадрат длины: 6² + 8² = 100.','Ұзындық квадраты: 6² + 8² = 100.'],['Длина равна 10 кварталам; маршрут был 14.','Ұзындық 10 квартал; маршрут 14 квартал болды.']],answer:'10 кварталов',answerText:['10 кварталов','10 квартал'],connection:['Вектор отделяет итоговое перемещение от пути по улицам.','Вектор қорытқы орын ауыстыруды көше жолынан ажыратады.'],takeaway:['Путь и перемещение отвечают на разные вопросы.','Жол мен орын ауыстыру әртүрлі сұрақтарға жауап береді.']},'6**2+8**2',100),
  'solids':e(['У пространственного тела есть длина, ширина и высота. Плоская картинка лишь показывает тело, а не отменяет третье измерение.','Кеңістік денесінің ұзындығы, ені және биіктігі бар. Жазық сурет денені көрсетеді, үшінші өлшемді жоймайды.'],[
    [['Грань, ребро, вершина','Жақ, қыр, төбе'],['Грань — плоская поверхность многогранника; ребро — общая сторона двух граней; вершина — место встречи рёбер. У прямоугольной коробки 6 граней, 12 рёбер и 8 вершин. Невидимые рёбра часто рисуют пунктиром.','Жақ — көпжақтың жазық беті; қыр — екі жақтың ортақ қабырғасы; төбе — қырлар кездесетін нүкте. Тіктөртбұрышты қорапта 6 жақ, 12 қыр, 8 төбе бар. Көрінбейтін қырлар үзік сызықпен беріледі.']],
    [['Восстанови скрытые части','Жасырын бөліктерді қалпына келтір'],['В рисунке куба наклонные линии могут обозначать прямые углы в пространстве. О свойствах суди по названию тела и условию. Развёртка переносит грани на плоскость: соседство граней помогает понять, какие стороны склеятся.','Куб суретіндегі көлбеу сызықтар кеңістіктегі тік бұрыштарды көрсетуі мүмкін. Қасиеттерді дене атауы мен шарттан анықта. Жазба жақтарды жазықтыққа көшіреді; көршілестік қай қабырғалардың қосылатынын түсіндіреді.']]
  ],[['Считай по типам','Түрлері бойынша сана'],['У прямоугольного параллелепипеда по четыре ребра каждой из трёх длин. Суммарная длина каркаса 4(a+b+c).','Тікбұрышты параллелепипедте үш ұзындықтың әрқайсысынан төрт қыр бар. Қаңқа ұзындығы 4(a+b+c).'],['Формула не относится к произвольному многограннику.','Формула кез келген көпжаққа қолданылмайды.']],{title:['Каркас коробки','Қорап қаңқасы'],problem:['Для модели прямоугольной коробки 2 × 3 × 4 дм нужен проволочный каркас. Найди длину проволоки без запаса на соединения.','2 × 3 × 4 дм қорап моделіне сым қаңқа керек. Қосылыстарға қор қоспай, сым ұзындығын тап.'],steps:[['Есть четыре ребра по 2, четыре по 3 и четыре по 4 дм.','2, 3 және 4 дм-ден төрт қырдан бар.'],['Складываем: 4·2 + 4·3 + 4·4.','Қосамыз: 4·2 + 4·3 + 4·4.'],['Получаем 36 дм.','36 дм аламыз.']],answer:'36 дм',connection:['Каркас требует длины рёбер, а не площади упаковки.','Қаңқа үшін қырлар ұзындығы керек, қаптама ауданы емес.'],takeaway:['Название материала помогает выбрать измеряемую величину.','Материал атауы қандай шаманы есептеуді көрсетеді.']},'4*(2+3+4)',36),
  'volumes':e(['Объём показывает, сколько пространства занимает тело. Можно мысленно заполнить его единичными кубиками и посчитать их количество.','Көлем дененің қанша кеңістік алатынын көрсетеді. Оны бірлік текшелермен ойша толтырып, санын есептеуге болады.'],[
    [['Площадь слоя и высота','Қабат ауданы мен биіктік'],['Для прямой призмы и цилиндра объём равен площади основания, умноженной на высоту. Это сумма одинаковых тонких слоёв. У пирамиды и конуса при тех же основании и высоте объём в три раза меньше.','Тік призма мен цилиндр көлемі табан ауданы мен биіктіктің көбейтіндісі. Бұл бірдей жұқа қабаттардың қосындысы. Табаны мен биіктігі бірдей пирамида мен конус көлемі үш есе аз.']],
    [['Согласуй единицы','Бірліктерді сәйкестендір'],['Перед умножением вырази все размеры в одной единице. 1 дм³ = 1 л, 1 м³ = 1000 л. Если сосуд заполнен только частично, используй высоту жидкости. Толщиной стенок можно пренебрегать лишь при указанной модели.','Көбейтуден бұрын барлық өлшемді бір бірлікке келтір. 1 дм³ = 1 л, 1 м³ = 1000 л. Ыдыс жартылай толса, сұйық биіктігін ал. Қабырға қалыңдығын тек модель шарты рұқсат етсе елеме.']]
  ],[['Переводи до расчёта','Есептеуге дейін түрлендір'],['Для литров удобно размеры перевести в дециметры: результат сразу будет в дм³, то есть литрах.','Литр үшін өлшемдерді дециметрге айналдыру ыңғайлы: нәтиже дм³, яғни литр болады.'],['Увеличение длины в 10 раз меняет объём в 1000 раз.','Ұзындықты 10 есе арттыру көлемді 1000 есе арттырады.']],{title:['Вода в аквариуме','Аквариумдағы су'],problem:['Внутренние размеры прямоугольного аквариума 6 × 3 дм, высота воды 2 дм. Сколько литров воды?','Тікбұрышты аквариум ішкі табаны 6 × 3 дм, су биіктігі 2 дм. Неше литр су бар?'],steps:[['Площадь основания 6·3 = 18 дм².','Табан ауданы 6·3 = 18 дм².'],['Объём воды 18·2 = 36 дм³.','Су көлемі 18·2 = 36 дм³.'],['1 дм³ = 1 л, значит 36 л.','1 дм³ = 1 л, демек 36 л.']],answer:'36 л',connection:['Объём переводится в вместимость сосуда.','Көлем ыдыс сыйымдылығына айналады.'],takeaway:['Берём внутренние размеры и фактическую высоту воды.','Ішкі өлшемдер мен нақты су биіктігін аламыз.']},'6*3*2',36),
  'space-vectors':e(['Пространственный вектор содержит три перемещения: по длине, ширине и высоте. Правила сложения остаются теми же, добавляется третья координата.','Кеңістік векторы ұзындық, ен және биіктік бойынша үш орын ауыстыруды қамтиды. Қосу ережесі сақталады, үшінші координата қосылады.'],[
    [['Вычитай конец минус начало','Соңынан басын азайт'],['Для A(x₁;y₁;z₁) и B(x₂;y₂;z₂) координаты AB равны (x₂−x₁;y₂−y₁;z₂−z₁). Отрицательная координата означает движение против выбранного положительного направления оси, а не отрицательную длину.','A(x₁;y₁;z₁), B(x₂;y₂;z₂) үшін AB = (x₂−x₁;y₂−y₁;z₂−z₁). Теріс координата осьтің оң бағытына қарсы қозғалысты білдіреді, теріс ұзындықты емес.']],
    [['Длина и угол','Ұзындық пен бұрыш'],['Длина (a;b;c) равна √(a²+b²+c²). Скалярное произведение двух векторов — сумма трёх произведений соответствующих координат. Для ненулевых векторов нулевое произведение означает перпендикулярность. Все координаты длин должны иметь одинаковые единицы.','(a;b;c) ұзындығы √(a²+b²+c²). Екі вектордың скаляр көбейтіндісі — сәйкес координаталар көбейтінділерінің қосындысы. Нөлдік емес векторлар үшін нөл нәтиже перпендикулярлықты білдіреді. Ұзындық координаталары бірдей бірлікте болуы керек.']]
  ],[['Сначала квадрат длины','Алдымен ұзындық квадраты'],['Пока сравниваешь расстояния, сравнивай суммы квадратов: извлекать корни часто не нужно.','Арақашықтықтарды салыстырғанда квадраттар қосындысын салыстыр: түбір алу жиі қажет емес.'],['При восстановлении длины выбирай неотрицательный корень.','Ұзындықты тапқанда теріс емес түбірді таңда.']],{title:['Перемещение подъёмника','Көтергіштің орын ауыстыруы'],problem:['В модели подъёмник переместил груз на 2 м вправо, 3 м вперёд и 6 м вверх. Найди длину результирующего перемещения.','Модельде көтергіш жүкті оңға 2 м, алға 3 м, жоғары 6 м жылжытты. Қорытқы орын ауыстыру ұзындығын тап.'],steps:[['Вектор (2;3;6) м.','Вектор (2;3;6) м.'],['Квадрат длины: 4+9+36 = 49 м².','Ұзындық квадраты: 4+9+36 = 49 м².'],['Длина √49 = 7 м.','Ұзындық √49 = 7 м.']],answer:'7 м',connection:['Прямое перемещение не равно сумме отдельных ходов механизма.','Тура орын ауыстыру механизм жүрістерінің қосындысына тең емес.'],takeaway:['Каждая координата описывает отдельную ось.','Әр координата жеке осьті сипаттайды.']},'2**2+3**2+6**2',49),
  'logic':e(['Логическая задача требует проверить утверждения, а не выбрать ответ, который звучит правдоподобно. Достаточно одного контрпримера, чтобы опровергнуть слово «всегда».','Логикалық есепте сенімді естілетін жауапты емес, тұжырымдарды тексереміз. «Әрқашан» сөзін жоққа шығару үшін бір қарсы мысал жеткілікті.'],[
    [['Разделяй «и» и «или»','«Және» мен «немесені» ажырат'],['Условие «A и B» требует выполнения обоих условий одновременно. «A или B» обычно допускает хотя бы одно, включая оба, если не написано «ровно одно». Переведи длинное предложение в короткие проверяемые условия.','«A және B» екі шарттың бір уақытта орындалуын талап етеді. «A немесе B» әдетте кемінде біреуін, екеуін де рұқсат етеді; «дәл біреу» бөлек шарт. Ұзын сөйлемді қысқа тексерілетін шарттарға бөл.']],
    [['Проверь все возможности','Барлық мүмкіндікті тексер'],['Для небольшого числа вариантов составь таблицу: строка — один кандидат, столбец — одно условие. Исключай строку при первом нарушении. Если подходит несколько строк, данных недостаточно для единственного ответа: не придумывай дополнительное условие.','Нұсқалар аз болса, кесте жаса: жол — үміткер, баған — шарт. Бір шарт бұзылса, жолды алып таста. Бірнеше жол сәйкес келсе, жалғыз жауапқа дерек жеткіліксіз; қосымша шарт ойлап таппа.']]
  ],[['Ищи границы условий','Шарт шекарасын ізде'],['Сначала проверь самое ограничивающее условие: оно быстрее сокращает список.','Алдымен ең шектеулі шартты тексер: ол тізімді жылдам қысқартады.'],['Исключение варианта должно иметь конкретную причину.','Нұсқаны алып тастаудың нақты себебі болуы керек.']],{title:['Выбор времени встречи','Кездесу уақытын таңдау'],problem:['Кружок может встретиться в 14, 15 или 16 часов. Айша свободна после 14, Данияр — до 16. Время задаётся целым часом. Какой вариант подходит обоим?','Үйірме 14, 15 не 16-да кездеседі. Айша 14-тен кейін, Данияр 16-ға дейін бос. Уақыт бүтін сағатпен берілген. Екеуіне қайсысы қолайлы?'],steps:[['После 14 означает t > 14: остаются 15 и 16.','14-тен кейін: t > 14, 15 пен 16 қалады.'],['До 16 означает t < 16: остаётся 15.','16-ға дейін: t < 16, 15 қалады.'],['15 выполняет оба условия.','15 екі шартты да орындайды.']],answer:'15:00',connection:['Пересечение условий помогает согласовать расписание.','Шарттардың қиылысуы кестені келісуге көмектеседі.'],takeaway:['«После» и «до» без включения границы дают строгие условия.','Шекараны қоспайтын «кейін» және «дейін» қатаң шарт береді.']},'(14+16)/2',15),
  'word-models':e(['Текстовая задача становится понятнее, когда слова превращаются в величины и связи между ними. Модель — упрощённое описание, сохраняющее нужные отношения.','Мәтіндік есеп сөздерді шамаларға және олардың байланысына айналдырғанда түсінікті болады. Модель — қажетті қатынастарды сақтайтын жеңілдетілген сипаттама.'],[
    [['Выбери одну неизвестную','Бір белгісізді таңда'],['Запиши, что означает x, и укажи единицу. Остальные неизвестные попробуй выразить через x. Слова «на 3 больше» дают x+3, «в 3 раза больше» — 3x. Это разные отношения, их нельзя заменять друг другом.','x нені білдіретінін және бірлігін жаз. Қалған белгісіздерді x арқылы өрнекте. «3-ке артық» — x+3, «3 есе артық» — 3x. Бұл әртүрлі қатынастар.']],
    [['Уравнение из баланса','Теңгерімнен теңдеу'],['Ищи равенство: общая стоимость, общее расстояние, сумма объёмов. После решения верни число в исходный текст и проверь смысл: количество предметов целое, длина положительная. Точное алгебраическое решение ещё должно соответствовать ситуации.','Жалпы баға, арақашықтық не көлем сияқты теңдікті ізде. Шешкен соң санды бастапқы мәтінге қой: зат саны бүтін, ұзындық оң болуы керек. Алгебралық шешім жағдайға да сәйкес келуі тиіс.']]
  ],[['Таблица «количество × цена»','«Саны × бағасы» кестесі'],['Для покупок отдельно запиши число предметов, цену одного и стоимость всей группы.','Сатып алуда зат саны, бір зат бағасы және топтың жалпы құнын бөлек жаз.'],['Скидка может применяться к одному товару, а не ко всей покупке.','Жеңілдік бүкіл сатып алуға емес, бір тауарға қолданылуы мүмкін.']],{title:['Билеты в музей','Мұражай билеттері'],problem:['Условная цена взрослого билета 1200 ₸, детского 600 ₸. Купили 5 билетов за 4200 ₸. Сколько детских?','Ересек билетінің шартты бағасы 1200 ₸, баланікі 600 ₸. 4200 ₸-ге 5 билет алынды. Балалар билеті нешеу?'],steps:[['Пусть x — детские; взрослых 5−x.','x — балалар билеті; ересектердікі 5−x.'],['600x + 1200(5−x) = 4200.','600x + 1200(5−x) = 4200.'],['6000−600x=4200, x=3; проверка: 1800+2400=4200.','6000−600x=4200, x=3; тексеру: 1800+2400=4200.']],answer:'3 детских билета',answerText:['3 детских билета','3 бала билеті'],connection:['Баланс стоимости создаёт линейное уравнение.','Құн теңгерімі сызықтық теңдеу береді.'],takeaway:['Ответ проверяется и по цене, и по числу билетов.','Жауап баға мен билет саны бойынша тексеріледі.']},'(6000-4200)/600',3),
  'charts':e(['Диаграмма — компактный рассказ о данных. Прежде чем считать, прочитай подписи: что измеряют, в каких единицах и за какой период.','Диаграмма — деректер туралы ықшам әңгіме. Есептеуден бұрын ненің, қандай бірлікпен және қай кезеңде өлшенгенін оқы.'],[
    [['Ось не всегда начинается с нуля','Ось әрқашан нөлден басталмайды'],['Столбцы сравнивают категории, линия часто показывает изменение во времени, круг — доли целого. На сокращённой вертикальной оси маленькая разница может выглядеть огромной. Оценивай значения по шкале, а не только по высоте картинки.','Бағандар санаттарды, сызық уақыттағы өзгерісті, дөңгелек бүтіннің үлестерін көрсетеді. Қысқартылған тік осьте аз айырма үлкен көрінуі мүмкін. Шамаларды тек сурет биіктігімен емес, шкаламен бағала.']],
    [['Абсолютное и относительное','Абсолют және салыстырмалы'],['Разность показывает изменение в единицах: новый результат минус старый. Процентное изменение делит эту разность на старое значение. Доли круговой диаграммы должны суммарно давать 100%, с возможной небольшой погрешностью округления.','Айырма бірліктердегі өзгерісті көрсетеді: жаңадан ескіні азайт. Пайыздық өзгеріс осы айырманы ескі мәнге бөледі. Дөңгелек диаграмма үлестері дөңгелектеу қатесін есепке алғанда 100% болуы керек.']]
  ],[['Подпиши считанные числа','Оқылған сандарды белгіле'],['Выпиши рядом с каждым числом категорию и единицу — это предотвращает сравнение разных показателей.','Әр санның жанына санат пен бірлікті жаз: әртүрлі көрсеткіштерді салыстырудан сақтайды.'],['График без исходных чисел иногда позволяет лишь приблизительную оценку.','Бастапқы сандарсыз график кейде тек жуық бағалау береді.']],{title:['Посещения библиотеки','Кітапханаға бару'],problem:['Учебная диаграмма показывает 80 посещений в понедельник и 100 во вторник. На сколько процентов выросло число посещений?','Оқу диаграммасында дүйсенбіде 80, сейсенбіде 100 келуші көрсетілген. Келушілер саны неше пайызға артты?'],steps:[['Прирост: 100−80 = 20 посещений.','Өсім: 100−80 = 20 келуші.'],['Сравниваем с исходным понедельником: 20/80 = 0,25.','Бастапқы дүйсенбімен салыстырамыз: 20/80 = 0,25.'],['0,25·100% = 25%.','0,25·100% = 25%.']],answer:'25%',connection:['Диаграмма даёт числа для процентного сравнения.','Диаграмма пайыздық салыстыруға сандар береді.'],takeaway:['Основание процента — исходное значение, здесь 80.','Пайыз негізі — бастапқы мән, мұнда 80.']},'(100-80)/80*100',25),
  'statistics':e(['Статистика помогает описать группу чисел одним или несколькими показателями. Один показатель не рассказывает всё: среднее может скрывать сильные различия.','Статистика сандар тобын бір не бірнеше көрсеткішпен сипаттайды. Бір көрсеткіш бәрін айтпайды: орташа үлкен айырмашылықтарды жасыруы мүмкін.'],[
    [['Среднее, медиана, мода','Орташа, медиана, мода'],['Среднее — сумма значений, делённая на их количество. Медиана — середина упорядоченного ряда; при чётном количестве берём среднее двух центральных значений. Мода — самое частое значение; мод может быть несколько или не быть единственной.','Орташа — мәндер қосындысының санына қатынасы. Медиана — реттелген қатардың ортасы; саны жұп болса, екі ортаңғы мәннің ортасын аламыз. Мода — ең жиі мән; бірнеше мода болуы мүмкін.']],
    [['Разброс и выброс','Шашырау мен ерекше мән'],['Размах равен максимуму минус минимум. Очень большое отдельное значение сильно сдвигает среднее, но обычно меньше влияет на медиану. Если значения имеют разные частоты, умножь каждое значение на его частоту и раздели на общее число наблюдений.','Құлаш ең үлкеннен ең кішіні азайтумен табылады. Бір өте үлкен мән орташаға қатты, медианаға көбіне азырақ әсер етеді. Жиіліктер әртүрлі болса, әр мәнді жиілігіне көбейтіп, бақылаулардың жалпы санына бөл.']]
  ],[['Сортировка перед медианой','Медиана алдында реттеу'],['Сначала упорядочь ряд. Порядок в условии может быть случайным, поэтому «среднее по месту» не всегда медиана.','Алдымен қатарды ретте. Шарттағы рет кездейсоқ болуы мүмкін, сондықтан ортадағы орын әрқашан медиана емес.'],['Не путай среднее значение со средним арифметическим границ диапазона.','Мәндердің ортасын аралық шекараларының ортасымен шатастырма.']],{title:['Время пути в школу','Мектепке бару уақыты'],problem:['За пять дней путь занял 12, 14, 13, 15 и 26 минут. Найди среднее и медиану.','Бес күнде жолға 12, 14, 13, 15 және 26 минут кетті. Орташа мен медиананы тап.'],steps:[['Сумма 80 минут; среднее 80/5 = 16 минут.','Қосынды 80 минут; орташа 80/5 = 16 минут.'],['Сортируем: 12, 13, 14, 15, 26.','Реттейміз: 12, 13, 14, 15, 26.'],['Третье значение — медиана 14 минут.','Үшінші мән — медиана 14 минут.']],answer:'Среднее 16 мин; медиана 14 мин',answerText:['Среднее 16 мин; медиана 14 мин','Орташа 16 мин; медиана 14 мин'],connection:['Один долгий день увеличил среднее время.','Бір ұзақ күн орташа уақытты арттырды.'],takeaway:['Для полного описания сравнивай несколько показателей.','Толық сипаттау үшін бірнеше көрсеткішті салыстыр.']},'(12+14+13+15+26)/5',16),
  'probability':e(['Вероятность — мера шанса события в заданной модели. Она лежит от 0 до 1; значение 1/2 не обещает чередование успеха и неудачи.','Ықтималдық — берілген модельдегі оқиға мүмкіндігінің өлшемі. Ол 0 мен 1 арасында; 1/2 мәні сәттілік пен сәтсіздіктің кезектесуін уәде етпейді.'],[
    [['Когда можно считать исходы','Нәтижелерді қашан санауға болады'],['Формула P = благоприятные исходы / все исходы работает, если исходы равновозможны. Сначала задай опыт: что выбирают и возвращают ли предмет обратно. Два последовательных выбора без возвращения меняют состав набора и вероятность второго выбора.','P = қолайлы нәтижелер / барлық нәтижелер формуласы нәтижелер тең мүмкін болғанда орындалады. Алдымен тәжірибені анықта: не таңдалады және зат қайтарыла ма? Қайтарусыз екінші таңдауда жиын құрамы мен ықтималдық өзгереді.']],
    [['Дополнение часто короче','Толықтауыш жиі қысқа'],['Вероятность противоположного события равна 1−P. Для независимых событий вероятность обоих — произведение вероятностей. Независимость должна следовать из модели; её нельзя предполагать только потому, что события названы разными словами.','Қарама-қарсы оқиға ықтималдығы 1−P. Тәуелсіз оқиғалардың бірге болу ықтималдығы олардың көбейтіндісі. Тәуелсіздік модельден шығуы керек; атаулары әртүрлі болуы жеткіліксіз.']]
  ],[['Сначала рисунок набора','Алдымен жиын суреті'],['Для маленького набора нарисуй предметы и отметь подходящие. Это помогает не пропустить знаменатель.','Шағын жиынның заттарын салып, қолайлыларын белгіле. Бұл бөлімді ұмытпауға көмектеседі.'],['Равное число цветов не означает равные вероятности, если шаров каждого цвета разное количество.','Түстер саны тең болса да, әр түстің шар саны әртүрлі болса, ықтималдықтары тең емес.']],{title:['Жребий из мешочка','Қалтадан жеребе'],problem:['В непрозрачном мешочке 3 синих и 2 красных одинаковых по размеру жетона. Случайно выбирают один. Какова вероятность синего?','Мөлдір емес қалтада өлшемі бірдей 3 көк және 2 қызыл жетон бар. Біреуі кездейсоқ алынады. Көк түстің ықтималдығы қандай?'],steps:[['Всего 3+2 = 5 равновозможных жетонов.','Барлығы 3+2 = 5 тең мүмкін жетон.'],['Подходят 3 синих.','3 көк жетон қолайлы.'],['P = 3/5 = 0,6 = 60%.','P = 3/5 = 0,6 = 60%.']],answer:'3/5 = 60%',connection:['Модель случайного выбора требует одинаковой возможности взять каждый жетон.','Кездейсоқ таңдау моделі әр жетонды алуға бірдей мүмкіндік талап етеді.'],takeaway:['Ответ — шанс в модели, а не гарантия следующего выбора.','Жауап — модельдегі мүмкіндік, келесі таңдаудың кепілі емес.']},'3/5',0.6),
  'dependencies':e(['Зависимость говорит, как одна величина изменяется вместе с другой. Формула полезна только вместе со смыслом переменных и областью её применения.','Тәуелділік бір шаманың екіншісімен бірге қалай өзгеретінін көрсетеді. Формула айнымалылар мағынасы және қолдану облысымен бірге пайдалы.'],[
    [['Прямая и обратная пропорциональность','Тура және кері пропорционалдық'],['В y = kx отношение y/x постоянно при x ≠ 0. Если есть фиксированная начальная плата, y = kx+b уже не прямая пропорциональность. В y = k/x постоянно произведение xy; нулевой x запрещён.','y = kx кезінде x ≠ 0 үшін y/x қатынасы тұрақты. Бастапқы тұрақты төлем болса, y = kx+b тура пропорционалдық емес. y = k/x үшін xy көбейтіндісі тұрақты, x = 0 болмайды.']],
    [['Проверяй единицы коэффициента','Коэффициент бірлігін тексер'],['Если x — километры, а y — тенге, k имеет единицу тенге за километр. Смысл коэффициента помогает проверить формулу. Не продолжай реальную зависимость за пределы тарифа, допустимой скорости или другой области модели без отдельного основания.','x километр, y теңге болса, k бірлігі — теңге/километр. Коэффициент мағынасы формуланы тексеруге көмектеседі. Нақты тәуелділікті тариф не модель шегінен негізсіз жалғастырма.']]
  ],[['Две точки отделяют базу от ставки','Екі нүкте база мен тарифті ажыратады'],['В линейной модели разность стоимости дели на разность расстояний: постоянная часть при вычитании исчезнет.','Сызықтық модельде құн айырмасын қашықтық айырмасына бөл: тұрақты бөлік азайтқанда жойылады.'],['При ступенчатом тарифе одной прямой может быть недостаточно.','Сатылы тарифке бір түзу жеткіліксіз болуы мүмкін.']],{title:['Условный тариф доставки','Шартты жеткізу тарифі'],problem:['Модель доставки: 500 ₸ за заказ и 120 ₸ за километр. Найди стоимость для 8 км.','Жеткізу моделі: тапсырысқа 500 ₸ және әр километрге 120 ₸. 8 км құнын тап.'],steps:[['Обозначим расстояние d; C = 500+120d.','Қашықтық d болсын; C = 500+120d.'],['Подставляем d = 8: переменная часть 960 ₸.','d = 8 қоямыз: айнымалы бөлік 960 ₸.'],['Общая цена 500+960 = 1460 ₸.','Жалпы баға 500+960 = 1460 ₸.']],answer:'1460 ₸',connection:['Начальная плата даёт свободный член формулы.','Бастапқы төлем формуланың бос мүшесін береді.'],takeaway:['Удвоение расстояния не удвоит всю цену с фиксированной платой.','Тұрақты төлемде қашықтықтың екі еселенуі бүкіл бағаны екі еселемейді.']},'500+120*8',1460),
  'patterns':e(['Закономерность — правило, связывающее элементы. Несколько чисел могут подходить под разные правила, поэтому продолжение зависит от явно выбранной модели.','Заңдылық — элементтерді байланыстыратын ереже. Бірнеше санға әртүрлі ереже сай болуы мүмкін, сондықтан жалғасы таңдалған модельге тәуелді.'],[
    [['Проверь разности и отношения','Айырма мен қатынасты тексер'],['Постоянная разность указывает на арифметическую прогрессию, постоянное отношение — на геометрическую, если предыдущие члены ненулевые. Если первые разности меняются регулярно, посмотри вторые разности. Но совпадение нескольких значений ещё не доказывает правило для всех n.','Тұрақты айырма арифметикалық прогрессияны, ал алдыңғы мүшелер нөл болмаса, тұрақты қатынас геометриялық прогрессияны көрсетеді. Бірінші айырмалар өзгерсе, екінші айырманы қара. Бірнеше сәйкестік барлық n үшін дәлел емес.']],
    [['Индекс тоже важен','Нөмір де маңызды'],['Укажи, с какого номера начинается ряд: n = 1 или n = 0. Формула aₙ = a₁+(n−1)d считает n−1 переходов от первого члена. Для рисунков определи, какие новые части добавляют на каждом шаге, чтобы не считать общие детали повторно.','Қатар n = 1-ден бе, n = 0-ден бе басталатынын көрсет. aₙ = a₁+(n−1)d формуласы бірінші мүшеден n−1 өтуді санайды. Суреттерде әр қадамдағы жаңа бөліктерді анықтап, ортақтарын қайталап санама.']]
  ],[['Проверь правило на всех данных','Ережені барлық деректе тексер'],['Подставь каждый известный номер, а не только первые два. Ошибка с индексом обычно обнаружится сразу.','Тек алғашқы екеуін емес, әр белгілі нөмірді қой. Нөмір қатесі әдетте бірден табылады.'],['Если правило не дано, называй найденное продолжение предположением.','Ереже берілмесе, жалғастыруды болжам деп ата.']],{title:['Ряды зрительного зала','Көрермен залының қатарлары'],problem:['В модели первый ряд содержит 12 мест, каждый следующий — на 2 больше. Сколько мест в шестом ряду?','Модельде бірінші қатарда 12 орын, әр келесі қатарда 2 орын артық. Алтыншы қатарда неше орын?'],steps:[['От первого до шестого ряда пять переходов.','Біріншіден алтыншыға бес өту бар.'],['Добавилось 5·2 = 10 мест.','5·2 = 10 орын қосылды.'],['a₆ = 12+10 = 22 места.','a₆ = 12+10 = 22 орын.']],answer:'22 места',answerText:['22 места','22 орын'],connection:['Условие явно задаёт постоянную разность.','Шарт тұрақты айырманы нақты береді.'],takeaway:['Номер ряда и число переходов отличаются на один.','Қатар нөмірі мен өту саны біреуге айырмашылық жасайды.']},'12+(6-1)*2',22),
  'geometric-logic':e(['В геометрической логике важно видеть структуру рисунка: какие части повторяются, какие пересекаются и что остаётся неизменным.','Геометриялық логикада сурет құрылымын көру маңызды: не қайталанады, не қиылысады және не өзгермейді.'],[
    [['Считай без повторов','Қайталаусыз сана'],['Если фигуры имеют общую сторону, она принадлежит рисунку один раз. При подсчёте всех треугольников или квадратов группируй их по размеру. Маленькие фигуры могут объединяться в большие, поэтому подсчёт только отдельных ячеек неполон.','Фигуралардың ортақ қабырғасы суретте бір рет саналады. Барлық үшбұрыш не шаршыны өлшемі бойынша топтастыр. Шағындары ірі фигура құрай алады, сондықтан тек ұяшықтарды санау жеткіліксіз.']],
    [['Назови сохраняемое свойство','Сақталатын қасиетті ата'],['При повороте фигуры сохраняются длины и углы. При разрезании и перестановке без наложений сохраняется площадь. Наблюдение превращается в решение, когда объяснено, почему свойство сохраняется и почему все варианты учтены.','Бұрғанда ұзындықтар мен бұрыштар сақталады. Қиып, қабаттастырмай орналастырғанда аудан сақталады. Қасиеттің неге сақталатыны және барлық нұсқа есептелгені түсіндірілсе, бақылау шешімге айналады.']]
  ],[['Добавляй одну фигуру','Бір фигурадан қос'],['Посчитай первый элемент, затем сколько новых деталей добавляет каждый следующий.','Алдымен бірінші элементті, кейін әр келесі элемент қосатын жаңа бөлшектерді сана.'],['Это работает только при одинаковом способе соединения.','Бұл тек бірдей қосылу тәсілінде орындалады.']],{title:['Ряд из спичечных квадратов','Шырпы шаршыларының қатары'],problem:['Пять квадратов стоят подряд и делят общую сторону с соседом. Для каждой стороны нужна одна спичка. Сколько спичек?','Бес шаршы қатар тұрып, көршісімен бір қабырғаны бөліседі. Әр қабырғаға бір шырпы керек. Неше шырпы қажет?'],steps:[['Первый квадрат требует 4 спички.','Бірінші шаршыға 4 шырпы керек.'],['Каждый из четырёх следующих добавляет 3, общая сторона уже есть.','Келесі төрт шаршының әрқайсысы 3 қосады, ортақ қабырға бар.'],['Итого 4+4·3 = 16.','Барлығы 4+4·3 = 16.']],answer:'16 спичек',answerText:['16 спичек','16 шырпы'],connection:['Повторяющаяся геометрия даёт арифметическую модель.','Қайталанатын геометрия арифметикалық модель береді.'],takeaway:['Общая деталь не должна считаться дважды.','Ортақ бөлшекті екі рет санама.']},'4+4*3',16),
  'practical-area':e(['В практической задаче площадь отвечает на вопрос о покрытии поверхности. Перед вычислением реши, какие участки покрываются, а какие исключаются.','Практикалық есепте аудан бетті жабуды сипаттайды. Алдымен қандай бөліктер жабылатынын, қайсысы алынатынын анықта.'],[
    [['Разбей сложную фигуру','Күрделі фигураны бөл'],['Г-образную комнату можно разделить на два прямоугольника или взять большой прямоугольник и вычесть отсутствующий угол. Оба способа допустимы, если части не перекрываются и полностью описывают нужную область. Нарисуй границы частей.','Г тәрізді бөлмені екі тіктөртбұрышқа бөл немесе үлкен тіктөртбұрыштан жоқ бұрышты алып таста. Бөліктер қабаттаспай, бүкіл аймақты қамтыса, екі тәсіл де дұрыс. Шекараларын сал.']],
    [['Количество материала','Материал мөлшері'],['Для плитки раздели площадь пола на площадь одной плитки, затем округли количество вверх. Но геометрическая площадь не учитывает раскрой и запас автоматически. Если запас задан в процентах, добавь его отдельно и укажи, к какой площади он относится.','Плитка санын еден ауданын бір плитка ауданына бөліп, жоғары дөңгелекте. Геометриялық аудан кесу мен қорды өздігінен есептемейді. Пайыздық қор берілсе, оны бөлек қосып, қай ауданға қатысты екенін көрсет.']]
  ],[['Вычитание удобнее разбиения','Азайту кейде бөлуден ыңғайлы'],['Если вырезан один прямоугольник, считай площадь внешнего прямоугольника минус вырез.','Бір тіктөртбұрыш кесілсе, сыртқы ауданнан кесілген ауданды азайт.'],['Все размеры переведи в одну единицу до умножения.','Көбейтуден бұрын өлшемдерді бір бірлікке келтір.']],{title:['Пол с нишей','Ойығы бар еден'],problem:['План пола — прямоугольник 6 × 4 м без прямоугольного участка 2 × 1 м. Найди площадь покрытия без запаса.','Еден жоспары 6 × 4 м тіктөртбұрыштан 2 × 1 м бөлікті алып тастағандай. Қорсыз жабын ауданын тап.'],steps:[['Полный прямоугольник: 6·4 = 24 м².','Толық тіктөртбұрыш: 6·4 = 24 м².'],['Исключённый участок: 2·1 = 2 м².','Алынған бөлік: 2·1 = 2 м².'],['Нужная площадь: 24−2 = 22 м².','Қажетті аудан: 24−2 = 22 м².']],answer:'22 м²',connection:['Вычитание площадей моделирует отверстие или недоступный участок.','Аудандарды азайту тесік не жабылмайтын бөлікті модельдейді.'],takeaway:['Запас материала и геометрическая площадь — отдельные расчёты.','Материал қоры мен геометриялық аудан бөлек есептеледі.']},'6*4-2*1',22),
  'surface':e(['Площадь поверхности считает внешние части тела. Объём описывает внутреннее пространство; одинаковые единицы длины дают разные степени единиц в ответе.','Бет ауданы дененің сыртқы бөліктерін есептейді. Көлем ішкі кеңістікті сипаттайды; жауапта бірліктердің дәрежелері әртүрлі.'],[
    [['Какие грани нужны','Қандай жақтар керек'],['Полная поверхность закрытой коробки включает все шесть граней. Коробка без крышки имеет пять покрываемых граней. При соединении тел общие внутренние грани не входят во внешнюю поверхность, поэтому простое сложение полных площадей может дать лишнее.','Жабық қораптың толық беті алты жақтан тұрады. Қақпақсыз қораптың жабылатын бес жағы бар. Денелер біріктірілсе, ішкі ортақ жақтар сыртқы бетке кірмейді, сондықтан толық аудандарды жай қосу артық нәтиже береді.']],
    [['Развёртка помогает','Жазба көмектеседі'],['Представь, что разрезал упаковку и разложил её на столе. Для прямоугольной коробки получаются пары прямоугольников ab, ac, bc. Общая площадь закрытой коробки 2(ab+ac+bc). Толщина, припуски и клеевые клапаны — отдельные условия реальной упаковки.','Қаптаманы қиып, үстелге жайғандай елестет. Тікбұрышты қорапта ab, ac, bc тіктөртбұрыштарының жұптары шығады. Жабық қорап ауданы 2(ab+ac+bc). Қалыңдық пен желімдеуге арналған қосымша бөліктер бөлек шарттар.']]
  ],[['Подпиши каждую грань','Әр жақты белгіле'],['Сначала перечисли покрываемые грани, затем складывай их площади.','Алдымен жабылатын жақтарды тізіп, кейін аудандарын қос.'],['В формуле полной поверхности не забудь вычесть отсутствующую крышку.','Толық бет формуласынан жоқ қақпақты азайтуды ұмытпа.']],{title:['Коробка без крышки','Қақпақсыз қорап'],problem:['Открытая сверху прямоугольная коробка имеет размеры 4 × 3 × 2 дм. Найди площадь картона без клапанов.','Үсті ашық тікбұрышты қорап 4 × 3 × 2 дм. Қосымша бөліктерсіз картон ауданын тап.'],steps:[['Дно: 4·3 = 12 дм².','Түбі: 4·3 = 12 дм².'],['Две длинные стенки: 2·4·2 = 16 дм²; две короткие: 2·3·2 = 12 дм².','Екі ұзын қабырға: 2·4·2 = 16 дм²; екі қысқа: 2·3·2 = 12 дм².'],['Итого 12+16+12 = 40 дм².','Барлығы 12+16+12 = 40 дм².']],answer:'40 дм²',connection:['Открытая упаковка требует неполной поверхности.','Ашық қаптамаға толық емес бет керек.'],takeaway:['Чертёж определяет, какие части входят в сумму.','Сызба қосындыға кіретін бөліктерді анықтайды.']},'4*3+2*4*2+2*3*2',40),
  'exponential-systems':e(['Система показательных уравнений требует найти пару, которая одновременно подходит обоим условиям. Удобно заменить повторяющиеся степени новыми переменными.','Көрсеткіштік теңдеулер жүйесінде екі шартқа бірдей сай жұп табылады. Қайталанатын дәрежелерді жаңа айнымалымен алмастыру ыңғайлы.'],[
    [['Замена с ограничением','Шектеуі бар алмастыру'],['Если встречаются 2ˣ и 2ʸ, обозначь u = 2ˣ, v = 2ʸ. Тогда u и v строго положительны. Реши получившуюся систему, затем вернись к x и y. Отрицательные значения u или v не соответствуют никаким действительным показателям.','2ˣ пен 2ʸ кездессе, u = 2ˣ, v = 2ʸ деп ал. u мен v қатаң оң. Жаңа жүйені шешіп, x пен y-ке қайт. Теріс u не v нақты көрсеткішке сәйкес келмейді.']],
    [['Проверка в двух уравнениях','Екі теңдеуде тексеру'],['Разные основания сначала приведи к одному, если это возможно: 4ˣ = (2ˣ)². Равенство показателей разрешено для одинакового основания a > 0, a ≠ 1. В конце подставь найденную пару в оба исходных равенства.','Мүмкін болса, әртүрлі негіздерді бірдей қыл: 4ˣ = (2ˣ)². Көрсеткіштерді a > 0, a ≠ 1 бірдей негізде теңестіруге болады. Соңында жұпты екі бастапқы теңдікке қой.']]
  ],[['Сумма и разность','Қосынды мен айырма'],['Для u+v и u−v сложение уравнений сразу даёт 2u, вычитание — 2v.','u+v пен u−v үшін теңдеулерді қосу 2u, азайту 2v береді.'],['После линейного решения ещё нужна обратная замена.','Сызықтық шешімнен кейін кері алмастыру қажет.']],{title:['Два канала роста','Екі өсу арнасы'],problem:['Учебная модель сигналов: A = 2ˣ, B = 2ʸ условных единиц. Измерено A+B=12, A−B=4. Найди показатели x и y.','Оқу сигнал моделі: A = 2ˣ, B = 2ʸ шартты бірлік. A+B=12, A−B=4 өлшенді. x пен y-ті тап.'],steps:[['Складываем: 2A=16, A=8.','Қосамыз: 2A=16, A=8.'],['B=12−8=4; оба значения положительны.','B=12−8=4; екеуі де оң.'],['2ˣ=8=2³, 2ʸ=4=2²: x=3, y=2.','2ˣ=8=2³, 2ʸ=4=2²: x=3, y=2.']],answer:'x=3; y=2',connection:['Это упрощённая модель восстановления двух интенсивностей, а не описание конкретного прибора.','Бұл екі қарқындылықты қалпына келтірудің жеңіл моделі, нақты құрал сипаттамасы емес.'],takeaway:['Заменённые переменные сохраняют ограничения исходных степеней.','Жаңа айнымалылар бастапқы дәрежелердің шектеулерін сақтайды.']},'(12+4)/2',8),
  'log-systems':e(['Логарифм переводит положительное число в показатель степени. В системе важно следить за положительностью каждого аргумента до любых преобразований.','Логарифм оң санды дәреженің көрсеткішіне айналдырады. Жүйеде кез келген түрлендіруден бұрын әр аргументтің оңдығын тексер.'],[
    [['Общая область','Ортақ облыс'],['Если система содержит log₂x и log₂y, сначала запиши x > 0 и y > 0. Формулы суммы и разности дают log₂(xy) и log₂(x/y) только для положительных x, y. Если аргументы сложнее, ограничения нужно пересечь.','Жүйеде log₂x пен log₂y болса, x > 0, y > 0 деп жаз. Қосынды мен айырма формулалары тек оң x, y үшін log₂(xy), log₂(x/y) береді. Күрделі аргументтер шектеулерінің қиылысуын ал.']],
    [['Восстановление величин','Шамаларды қалпына келтіру'],['Можно обозначить u = log₂x, v = log₂y и решить линейную систему. Затем x = 2ᵘ, y = 2ᵛ. Не путай логарифм суммы с суммой логарифмов: log(x+y) обычно не равен log x + log y.','u = log₂x, v = log₂y деп сызықтық жүйе шешуге болады. Кейін x = 2ᵘ, y = 2ᵛ. Қосынды логарифмін логарифмдер қосындысымен шатастырма: log(x+y) әдетте log x + log y емес.']]
  ],[['Сначала реши показатели','Алдымен көрсеткіштерді шеш'],['Одинаковые логарифмы в обоих уравнениях удобно считать отдельными неизвестными.','Екі теңдеудегі бірдей логарифмдерді жеке белгісіз деп алу ыңғайлы.'],['Обратная замена обязательна: u — не исходный x.','Кері алмастыру міндетті: u бастапқы x емес.']],{title:['Логарифмические показания','Логарифмдік көрсеткіштер'],problem:['Модель датчиков показывает log₂x + log₂y = 5 и log₂x − log₂y = 1. x и y — положительные безразмерные отношения. Найди их.','Датчик моделі log₂x + log₂y = 5 және log₂x − log₂y = 1 көрсетеді. x пен y — оң өлшемсіз қатынастар. Оларды тап.'],steps:[['u+v=5, u−v=1, поэтому 2u=6 и u=3.','u+v=5, u−v=1, сондықтан 2u=6, u=3.'],['v=5−3=2.','v=5−3=2.'],['x=2³=8, y=2²=4; логарифмы 3 и 2 дают 5 и 1.','x=2³=8, y=2²=4; 3 пен 2 логарифмдері 5 пен 1 береді.']],answer:'x=8; y=4',connection:['Шкала логарифмов помогает восстановить исходные отношения.','Логарифм шкаласы бастапқы қатынастарды табуға көмектеседі.'],takeaway:['Аргумент логарифма должен быть положительным и корректно заданным.','Логарифм аргументі оң және дұрыс берілген болуы керек.']},'2**((5+1)/2)',8),
  'irrational-systems':e(['В иррациональной системе неизвестные находятся под корнями. Квадратный корень означает неотрицательное значение, что ограничивает возможные решения.','Иррационал жүйеде белгісіздер түбір астында болады. Квадрат түбір теріс емес мәнді білдіреді, бұл шешімдерді шектейді.'],[
    [['Замена корней','Түбірлерді алмастыру'],['Если повторяются √x и √y, введи u = √x, v = √y. Тогда u ≥ 0, v ≥ 0, x = u², y = v². После решения замены отрицательные u или v исключаются, даже если их квадраты положительны.','√x пен √y қайталанса, u = √x, v = √y деп ал. u ≥ 0, v ≥ 0, x = u², y = v². Теріс u, v квадраттары оң болса да қабылданбайды.']],
    [['Квадрат может добавить корни','Квадрат артық түбір қосуы мүмкін'],['При возведении равенства в квадрат знак исчезает: 3² = (−3)². Поэтому квадратирование не всегда равносильно исходному равенству. Если корень изолирован, правая часть должна быть неотрицательна. Проверяй пару в каждом исходном уравнении.','Теңдікті квадраттағанда таңба жоғалады: 3² = (−3)². Сондықтан квадраттау әрқашан мәндес емес. Түбір жеке тұрса, оң жақ теріс емес болуы керек. Жұпты әр бастапқы теңдеуде тексер.']]
  ],[['Реши в длинах, не в квадратах','Квадраттармен емес, ұзындықтармен шеш'],['Для суммы корней линейная замена часто проще многократного квадратирования.','Түбірлер қосындысына сызықтық алмастыру қайта-қайта квадраттаудан жеңіл.'],['Замена √x требует x ≥ 0 и неотрицательного нового неизвестного.','√x алмастыруы x ≥ 0 және теріс емес жаңа белгісізді талап етеді.']],{title:['Стороны двух квадратных панелей','Екі шаршы панель қабырғасы'],problem:['Площади панелей x и y м². Сумма сторон 7 м, разность 1 м. Найди площади, считая первую панель большей.','Панель аудандары x және y м². Қабырғалар қосындысы 7 м, айырмасы 1 м. Біріншісі үлкен болса, аудандарды тап.'],steps:[['u=√x, v=√y: u+v=7, u−v=1.','u=√x, v=√y: u+v=7, u−v=1.'],['2u=8, u=4 м, v=3 м — оба неотрицательны.','2u=8, u=4 м, v=3 м — екеуі де теріс емес.'],['x=16 м², y=9 м²; стороны дают 7 и 1.','x=16 м², y=9 м²; қабырғалар 7 және 1 береді.']],answer:'16 м²; 9 м²',connection:['Корень площади квадрата равен его стороне.','Шаршы ауданының түбірі оның қабырғасына тең.'],takeaway:['В проверке вернись к длинам сторон.','Тексеруде қабырға ұзындықтарына қайт.']},'((7+1)/2)**2',16),
  'trig-systems':e(['Синус и косинус одного угла связаны равенством sin²x + cos²x = 1. Система может задавать сразу две координаты точки на единичной окружности.','Бір бұрыштың синусы мен косинусы sin²x + cos²x = 1 арқылы байланысты. Жүйе бірлік шеңбер нүктесінің екі координатасын бере алады.'],[
    [['Совместимость условий','Шарттардың үйлесімділігі'],['Если заданы sin x = a и cos x = b, проверь a²+b²=1. Иначе действительного угла нет. Знаки a и b определяют четверть. Один синус допускает два положения на окружности; второй параметр убирает неоднозначность.','sin x = a, cos x = b болса, a²+b²=1 тексер. Орындалмаса, нақты бұрыш жоқ. a мен b таңбалары ширекті анықтайды. Бір синус екі орынға сай болуы мүмкін, екінші шарт екіұштылықты жояды.']],
    [['Не потеряй период','Периодты жоғалтпа'],['Для пары синуса и косинуса угол повторяется через 2π радиан, то есть 360°. Если нужен общий ответ, добавь 2πk, k ∈ ℤ. Если время или угол ограничены интервалом, выбери только решения внутри него.','Синус пен косинус жұбы 2π радианнан, яғни 360°-тан кейін қайталанады. Жалпы жауапқа 2πk, k ∈ ℤ қос. Уақыт не бұрыш аралықпен шектелсе, тек сол аралықтағы шешімдерді таңда.']]
  ],[['Сначала четверть','Алдымен ширек'],['Два отрицательных значения указывают на третью четверть. Найди опорный угол и размести его в нужной четверти.','Екі теріс мән үшінші ширекті көрсетеді. Тірек бұрышты тауып, қажетті ширекке орналастыр.'],['Не заменяй cos x положительным корнем без проверки его знака.','cos x таңбасын тексермей, оны оң түбірмен алмастырма.']],{title:['Положение вращающегося указателя','Айналатын көрсеткіш орны'],problem:['В учебной модели единичного диска координаты указателя cos θ = −√2/2, sin θ = −√2/2. Найди θ в [0°;360°).','Бірлік диск моделінде көрсеткіш координаталары cos θ = −√2/2, sin θ = −√2/2. θ-ны [0°;360°) аралығында тап.'],steps:[['Квадраты координат дают 1/2+1/2=1: данные совместимы.','Координаталар квадраттары 1/2+1/2=1: деректер үйлеседі.'],['Оба знака отрицательны, это третья четверть.','Екі таңба теріс, бұл үшінші ширек.'],['Опорный угол 45°; θ=180°+45°=225°.','Тірек бұрыш 45°; θ=180°+45°=225°.']],answer:'225°',connection:['Два измерения однозначно определяют положение за один оборот.','Екі өлшем бір айналымдағы орынды бірмәнді анықтайды.'],takeaway:['Координаты нужно проверять вместе, а не решать отдельно.','Координаталарды бөлек емес, бірге тексер.']},'180+45',225),
  'exponential-inequalities':e(['Показательная функция либо возрастает, либо убывает. Именно это определяет, сохраняется ли знак неравенства при сравнении показателей.','Көрсеткіштік функция өседі не кемиді. Көрсеткіштерді салыстырғанда теңсіздік таңбасының сақталуы осыған тәуелді.'],[
    [['Основание больше единицы','Негіз бірден үлкен'],['При a > 1 из aᵘ ≤ aᵛ следует u ≤ v. Сначала приведи обе стороны к одному основанию. Например, 8 = 2³. Положительность степени позволяет сравнивать значения, но не разрешает складывать показатели при сложении степеней.','a > 1 болса, aᵘ ≤ aᵛ-ден u ≤ v шығады. Алдымен екі жағын бір негізге келтір, мысалы 8 = 2³. Дәрежелерді қосқанда көрсеткіштерді жай қосуға болмайды.']],
    [['Основание между нулём и единицей','Негіз нөл мен бір арасында'],['Для 0 < a < 1 функция убывает: aᵘ ≤ aᵛ означает u ≥ v. Чем больше показатель, тем меньше результат. После решения учти область задачи: время часто неотрицательно, а число периодов иногда целое.','0 < a < 1 кезінде функция кемиді: aᵘ ≤ aᵛ болса u ≥ v. Көрсеткіш артқан сайын нәтиже азаяды. Есеп облысын ескер: уақыт теріс емес, кезең саны кейде бүтін.']]
  ],[['Проверь одним числом','Бір санмен тексер'],['Подставь число по одну сторону границы: так быстро заметишь случайно перевёрнутый знак.','Шекараның бір жағынан сан қой: қате аударылған таңбаны тез байқайсың.'],['Проверка одной точки дополняет доказательство монотонностью, но не заменяет его.','Бір нүкте монотондылық дәлелін толықтырады, бірақ алмастырмайды.']],{title:['Уменьшение запаса','Қордың азаюы'],problem:['В условной модели после каждого дня остаётся половина запаса: Q=80·(1/2)ᵗ. Когда Q ≤ 10, если t — целое число дней ≥0?','Шартты модельде әр күннен кейін қордың жартысы қалады: Q=80·(1/2)ᵗ. t ≥0 бүтін күн болса, Q ≤10 қашан?'],steps:[['Делим на 80: (1/2)ᵗ ≤1/8=(1/2)³.','80-ге бөлеміз: (1/2)ᵗ ≤1/8=(1/2)³.'],['Основание 1/2 <1, поэтому t ≥3.','1/2 <1 болғандықтан, t ≥3.'],['На третий день Q=10; позже ещё меньше.','Үшінші күнде Q=10; кейін одан аз.']],answer:'t ≥ 3 дня',answerText:['t ≥ 3 дня','t ≥ 3 күн'],connection:['Это модель последовательного уменьшения, не медицинская рекомендация.','Бұл біртіндеп азаю моделі, медициналық кеңес емес.'],takeaway:['При убывающей степени направление сравнения меняется.','Кемитін дәрежеде салыстыру бағыты өзгереді.']},'80*(1/2)**3',10),
  'log-inequalities':e(['Логарифмическое неравенство решается только там, где аргументы положительны. Область допустимых значений — часть ответа, а не дополнительная заметка.','Логарифмдік теңсіздік аргументтер оң жерде ғана шешіледі. Мүмкін мәндер облысы — жауаптың бөлігі.'],[
    [['Основание управляет знаком','Негіз таңбаны басқарады'],['При a >1 логарифм возрастает, при 0<a<1 убывает. Поэтому logₐu < logₐv превращается в u<v в первом случае и u>v во втором. В обоих случаях u>0 и v>0 должны выполняться.','a >1 болса логарифм өседі, 0<a<1 болса кемиді. logₐu < logₐv бірінші жағдайда u<v, екіншісінде u>v береді. Екі жағдайда да u>0, v>0 болуы тиіс.']],
    [['Пересечение с ОДЗ','ММO-мен қиылысу'],['Если получено x≤9, но логарифм содержит x−1, итог ещё требует x>1. Для дробного аргумента нельзя просто объявить отдельно числитель и знаменатель положительными: дробь положительна также при двух отрицательных частях.','x≤9 шықса, бірақ логарифмде x−1 болса, x>1 де керек. Бөлшек аргументте алым мен бөлімді жеке оң деп қоюға болмайды: екеуі теріс болса да бөлшек оң.']]
  ],[['Число запиши логарифмом','Санды логарифммен жаз'],['2 = log₁₀100 помогает сравнить аргументы, но сначала проверь основание.','2 = log₁₀100 аргументтерді салыстыруға көмектеседі, алдымен негізді тексер.'],['log(u+v) нельзя разбить на log u + log v.','log(u+v)-ні log u + log v-ге бөлуге болмайды.']],{title:['Логарифмический индекс нагрузки','Жүктеменің логарифмдік индексі'],problem:['Учебный индекс I=log₂(1+N), где N≥0 — число условных запросов. Найди N, при которых I≤3.','Оқу индексі I=log₂(1+N), N≥0 — шартты сұраулар саны. I≤3 болатын N-дерді тап.'],steps:[['ОДЗ: 1+N>0, при N≥0 она выполнена.','ММО: 1+N>0, N≥0 кезінде орындалады.'],['Основание 2>1: 1+N≤2³=8.','Негіз 2>1: 1+N≤2³=8.'],['N≤7; вместе с условием 0≤N≤7, для числа запросов берём целые.','N≤7; шартпен бірге 0≤N≤7, сұраулар саны үшін бүтін мәндер аламыз.']],answer:'N ∈ {0,1,2,3,4,5,6,7}',connection:['Логарифмическая шкала сжимает большие диапазоны чисел.','Логарифм шкаласы үлкен сан аралығын ықшамдайды.'],takeaway:['Решение неравенства пересекается с физическим смыслом переменной.','Теңсіздік шешімі айнымалының нақты мағынасымен қиылысады.']},'2**3-1',7),
  'irrational-inequalities':e(['Неравенство с квадратным корнем сначала требует неотрицательного подкоренного выражения. Сравнение с отрицательным числом часто можно решить без квадратирования.','Квадрат түбірі бар теңсіздікте алдымен түбір асты теріс емес болуы тиіс. Теріс санмен салыстыру жиі квадраттаусыз шешіледі.'],[
    [['Квадратирование с условиями','Шартпен квадраттау'],['Для √u ≤ v необходимы u≥0 и v≥0; тогда можно перейти к u≤v². Если v<0, решений нет. Для √u ≥ v при v≤0 достаточно u≥0, ведь любой квадратный корень неотрицателен.','√u ≤ v үшін u≥0, v≥0 қажет; сонда u≤v²-ге өтеміз. v<0 болса, шешім жоқ. √u ≥ v және v≤0 кезінде u≥0 жеткілікті, себебі квадрат түбір теріс емес.']],
    [['Не потеряй границу','Шекараны жоғалтпа'],['Равенство под корнем нулю допустимо. При строгом неравенстве границу сравнения исключают, но нулевая точка ОДЗ может остаться. Вычисли итог как пересечение условий, затем проверь граничные значения отдельно.','Түбір астының нөл болуы рұқсат. Қатаң теңсіздікте салыстыру шекарасы алынбайды, бірақ ММО-ның нөл нүктесі қалуы мүмкін. Шарттардың қиылысуын алып, шекараларды жеке тексер.']]
  ],[['Сначала знак правой части','Алдымен оң жақ таңбасы'],['Перед квадратированием спроси: обе стороны неотрицательны? Если нет, раздели на случаи.','Квадраттаудан бұрын екі жақ та теріс емес пе деп сұра. Жоқ болса, жағдайларға бөл.'],['Квадратирование отрицательных частей может изменить неравенство.','Теріс бөліктерді квадраттау теңсіздікті өзгертуі мүмкін.']],{title:['Длина стороны панели','Панель қабырғасының ұзындығы'],problem:['Квадратная панель площади A м² должна иметь сторону не длиннее 3 м. Какие площади подходят?','Ауданы A м² шаршы панельдің қабырғасы 3 м-ден ұзын болмауы тиіс. Қандай аудандар сай?'],steps:[['Сторона √A, поэтому A≥0.','Қабырға √A, сондықтан A≥0.'],['√A≤3; обе стороны неотрицательны.','√A≤3; екі жақ теріс емес.'],['Квадратируем: A≤9. Итог 0≤A≤9; для ненулевой панели A>0.','Квадраттаймыз: A≤9. Қорытынды 0≤A≤9; нөлдік емес панель үшін A>0.']],answer:'0 < A ≤ 9 м² для ненулевой панели',answerText:['0 < A ≤ 9 м² для ненулевой панели','Нөлдік емес панельге 0 < A ≤ 9 м²'],connection:['Корень связывает площадь с ограничением на длину.','Түбір ауданды ұзындық шектеуімен байланыстырады.'],takeaway:['Математически нулевой случай допустим, но реальная панель должна иметь площадь.','Математикада нөлдік жағдай мүмкін, нақты панельдің ауданы болуы тиіс.']},'3**2',9),
  'trig-inequalities':e(['Тригонометрическое неравенство выбирает дуги окружности, а не отдельные точки. Повторение через период создаёт бесконечное семейство интервалов.','Тригонометриялық теңсіздік жеке нүктелерді емес, шеңбер доғаларын таңдайды. Периодпен қайталану шексіз аралықтар отбасын береді.'],[
    [['Смотри на координату','Координатаға қара'],['На единичной окружности cos x — горизонтальная координата, sin x — вертикальная. Для sin x≥1/2 выбираем точки выше горизонтали y=1/2. Граничные углы π/6 и 5π/6 входят из-за знака ≥.','Бірлік шеңберде cos x — көлденең, sin x — тік координата. sin x≥1/2 үшін y=1/2-ден жоғары нүктелерді аламыз. ≥ болғандықтан π/6 және 5π/6 шекаралары кіреді.']],
    [['Аргумент может быть сложнее','Аргумент күрделі болуы мүмкін'],['Если внутри синуса 2x, сначала реши для t=2x, затем раздели все границы и период на два. В выражениях с тангенсом исключай точки, где cos x=0. Всегда проверяй, используешь градусы или радианы.','Синуста 2x болса, алдымен t=2x үшін шешіп, барлық шекара мен периодты екіге бөл. Тангенсте cos x=0 нүктелерін алып таста. Градус па, радиан ба екенін тексер.']]
  ],[['Один период, потом повторение','Бір период, кейін қайталау'],['Найди подходящую дугу в одном обороте, затем добавь 2πk или 360°k.','Бір айналымда тиісті доғаны тауып, 2πk не 360°k қос.'],['Для cos и sin интервалы расположены по-разному.','cos пен sin аралықтарының орналасуы әртүрлі.']],{title:['Высота вращающегося маркера','Айналатын маркер биіктігі'],problem:['В модели колесо радиуса 2 м имеет центр на высоте 3 м. Высота маркера h=3+2sin θ. При каких θ∈[0°;360°) h≥4 м?','Модельде радиусы 2 м дөңгелек центрі 3 м биіктікте. Маркер биіктігі h=3+2sin θ. θ∈[0°;360°) үшін h≥4 м қашан?'],steps:[['3+2sin θ≥4 даёт sin θ≥1/2.','3+2sin θ≥4 теңсіздігі sin θ≥1/2 береді.'],['На окружности это верхняя дуга от 30° до 150°.','Шеңберде бұл 30°-тан 150°-қа дейінгі жоғарғы доға.'],['Границы включены: θ∈[30°;150°].','Шекаралар кіреді: θ∈[30°;150°].']],answer:'θ ∈ [30°;150°]',connection:['Синус моделирует вертикальную координату равномерного вращения.','Синус айналудың тік координатасын модельдейді.'],takeaway:['Интервал времени получают только после задания скорости вращения.','Уақыт аралығы тек айналу жылдамдығы берілсе табылады.']},'(4-3)/2',0.5),
  'linear-inequality-systems':e(['Система означает одновременное выполнение всех неравенств. Ответ — общая часть их решений, а не объединение всех разрешённых чисел.','Жүйе барлық теңсіздіктің бір уақытта орындалуын білдіреді. Жауап — шешімдердің ортақ бөлігі, барлық рұқсат сандардың бірігуі емес.'],[
    [['Реши каждую строку','Әр жолды шеш'],['Линейное неравенство решается переносом и делением на коэффициент. При делении на отрицательное число знак меняется. Пустое пересечение означает, что никакое число не выполняет систему; это полноценный ответ.','Сызықтық теңсіздік мүшелерді көшіру және коэффициентке бөлу арқылы шешіледі. Теріс санға бөлгенде таңба өзгереді. Бос қиылысу еш сан жүйені орындамайтынын білдіреді; бұл толық жауап.']],
    [['Отметь границы','Шекараларды белгіле'],['На числовой прямой строгую границу рисуй пустым кружком, нестрогую — закрашенным. Если одна граница строже другой в том же направлении, остаётся более строгая. Переменная задачи может дополнительно быть целой или неотрицательной.','Сан осінде қатаң шекара бос, қатаң емес шекара боялған нүкте болады. Бір бағыттағы екі шектеудің қатаңырағы қалады. Есеп айнымалысы қосымша бүтін не теріс емес болуы мүмкін.']]
  ],[['Собери нижние и верхние границы','Төменгі және жоғарғы шектерді жина'],['Самая большая нижняя граница и самая маленькая верхняя определяют пересечение.','Ең үлкен төменгі және ең кіші жоғарғы шек қиылысуды анықтайды.'],['Отдельно проверь включение концов.','Ұштардың кіретінін бөлек тексер.']],{title:['Покупка тетрадей','Дәптер сатып алу'],problem:['Тетрадь условно стоит 250 ₸. Нужно не меньше 4 тетрадей, бюджет 1500 ₸. Какие количества допустимы?','Дәптер шартты түрде 250 ₸. Кемінде 4 дәптер керек, бюджет 1500 ₸. Қандай сандар мүмкін?'],steps:[['n≥4 и 250n≤1500.','n≥4 және 250n≤1500.'],['Делим вторую строку на 250: n≤6.','Екінші жолды 250-ге бөлеміз: n≤6.'],['Пересечение 4≤n≤6; n целое: 4,5,6.','Қиылысу 4≤n≤6; n бүтін: 4,5,6.']],answer:'4, 5 или 6 тетрадей',answerText:['4, 5 или 6 тетрадей','4, 5 не 6 дәптер'],connection:['Минимальная потребность и максимальный бюджет задают две границы.','Ең аз қажеттілік пен ең үлкен бюджет екі шек береді.'],takeaway:['Система описывает выполнимый диапазон решения.','Жүйе орындалатын шешім ауқымын сипаттайды.']},'1500/250',6),
  'rational-inequality-systems':e(['В рациональных неравенствах неизвестная может быть в знаменателе. Нули знаменателя исключаются независимо от знака сравнения.','Рационал теңсіздіктерде белгісіз бөлімде болуы мүмкін. Бөлім нөлдері теңсіздік таңбасына қарамастан алынады.'],[
    [['Не умножай на неизвестный знак','Белгісіз таңбаға көбейтпе'],['Умножение на x−1 без знания его знака может потерять решения. Вместо этого перенеси всё в одну сторону, приведи к дроби и отметь нули числителя и знаменателя. На каждом промежутке знак постоянен, если учтены все критические точки.','x−1 таңбасын білмей көбейту шешім жоғалтады. Бәрін бір жаққа көшіріп, бөлшекке келтір, алым мен бөлім нөлдерін белгіле. Барлық сын нүкте ескерілсе, әр аралықта таңба тұрақты.']],
    [['Общее решение системы','Жүйенің ортақ шешімі'],['Для каждого неравенства выпиши интервалы отдельно, затем найди пересечение. Нули числителя допускаются при ≤ или ≥, если знаменатель там ненулевой. Нули знаменателя никогда не допускаются, даже если дробь можно формально сократить.','Әр теңсіздік аралықтарын бөлек жазып, қиылысуын тап. ≤ не ≥ кезінде алым нөлдері бөлім нөл болмаса кіреді. Бөлім нөлдері, бөлшек қысқарса да, ешқашан кірмейді.']]
  ],[['Запиши ОДЗ на полях','ММО-ны шетке жаз'],['Держи запрещённые точки видимыми до окончательного ответа.','Тыйым салынған нүктелерді соңғы жауапқа дейін көрінетіндей жаз.'],['Сокращение множителя не возвращает запрещённое значение.','Көбейткішті қысқарту тыйым мәнді қайтармайды.']],{title:['Две нормы производительности','Өнімділіктің екі шарты'],problem:['В условной модели x>0 — скорость. Нужно 12/x≤3 часов на работу и x/(x+2)≥1/2 — безразмерный показатель. Найди допустимые x.','Шартты модельде x>0 — жылдамдық. Жұмысқа 12/x≤3 сағат және өлшемсіз x/(x+2)≥1/2 керек. Мүмкін x-терді тап.'],steps:[['При x>0 первая строка даёт 12≤3x, x≥4.','x>0 кезінде бірінші жол 12≤3x, x≥4 береді.'],['x+2>0: 2x≥x+2, x≥2.','x+2>0: 2x≥x+2, x≥2.'],['Пересечение x≥4; знаменатели ненулевые.','Қиылысу x≥4; бөлімдер нөл емес.']],answer:'x ≥ 4',connection:['Модель показывает пересечение ограничения времени и показателя эффективности.','Модель уақыт пен тиімділік шектеулерінің қиылысуын көрсетеді.'],takeaway:['Здесь умножение безопасно только благодаря явно указанному x>0.','Мұнда көбейту тек нақты x>0 шарты арқасында қауіпсіз.']},'12/3',4),
  'nonlinear-inequality-systems':e(['Нелинейное неравенство может иметь несколько отдельных интервалов решения. Система оставляет только числа, проходящие все проверки одновременно.','Сызықтық емес теңсіздіктің бірнеше бөлек шешім аралығы болуы мүмкін. Жүйе барлық тексеруден бір уақытта өтетін сандарды қалдырады.'],[
    [['Границы из корней','Түбірлерден шекаралар'],['Для квадратного выражения найди корни и направление ветвей параболы. При положительном старшем коэффициенте выражение не больше нуля между корнями. Неравенство без действительных корней может выполняться всегда или никогда — проверь знак.','Квадрат өрнек үшін түбірлер мен парабола тармақтарының бағытын тап. Бас коэффициент оң болса, өрнек түбірлер арасында нөлден үлкен емес. Нақты түбірсіз теңсіздік әрқашан не ешқашан орындалуы мүмкін — таңбаны тексер.']],
    [['Пересечение областей','Облыстардың қиылысуы'],['Если переменных две, каждое условие задаёт область на плоскости. Прямая, парабола и окружность образуют разные границы. Закрашивай пробную точку для выбора стороны и отдельно выясняй, включена ли граница. Рисунок помогает, но ответ должен описывать точные условия.','Айнымалы екеу болса, әр шарт жазықтық облысын береді. Түзу, парабола, шеңбер әртүрлі шекара жасайды. Жақты таңдау үшін сынақ нүктесін тексеріп, шекараның кіретінін анықта. Сурет көмектеседі, жауап дәл шарттарды сипаттауы тиіс.']]
  ],[['Раздели вычисление и пересечение','Есептеу мен қиылысуды бөл'],['Не пытайся решать все строки сразу: найди каждую область, затем наложи их.','Барлық жолды бірден шешпе: әр облысты тауып, кейін қабаттастыр.'],['Условие «или» требует объединения, система обычно означает «и».','«Немесе» бірігуді, жүйе әдетте «және» қиылысуын талап етеді.']],{title:['Допустимая высота конструкции','Құрылымның мүмкін биіктігі'],problem:['Учебная модель требует h²−5h+6≤0 и h≥2,5 м. Найди допустимую высоту h.','Оқу моделі h²−5h+6≤0 және h≥2,5 м талап етеді. Мүмкін h биіктігін тап.'],steps:[['Разложим: (h−2)(h−3)≤0.','Жіктейміз: (h−2)(h−3)≤0.'],['Парабола направлена вверх: 2≤h≤3.','Парабола жоғары бағытталған: 2≤h≤3.'],['Пересекаем с h≥2,5: 2,5≤h≤3 м.','h≥2,5-пен қиылыстырамыз: 2,5≤h≤3 м.']],answer:'h ∈ [2,5;3] м',connection:['Ограничения заданы как учебная модель, не строительная норма.','Шектеулер құрылыс нормасы емес, оқу моделі ретінде берілген.'],takeaway:['Квадратное условие может ограничивать сразу снизу и сверху.','Квадрат шарт бірден төменнен және жоғарыдан шектей алады.']},'3**2-5*3+6',0),
  'exponential-inequality-systems':e(['Для системы показательных неравенств направление сравнения определяется отдельно для каждого основания. Один знак нельзя механически копировать в другую строку.','Көрсеткіштік теңсіздіктер жүйесінде салыстыру бағыты әр негізге жеке анықталады. Бір таңбаны екінші жолға механикалық көшірме.'],[
    [['Решай с монотонностью','Монотондылықпен шеш'],['При основании больше единицы показатели сравниваются в том же порядке. При основании между нулём и единицей порядок противоположный. Если в системе основания 2 и 1/2, одна функция растёт, другая убывает.','Негіз бірден үлкен болса, көрсеткіштер сол ретпен салыстырылады. Негіз нөл мен бір арасында болса, рет кері. Жүйеде 2 және 1/2 болса, бір функция өсіп, екіншісі кемиді.']],
    [['Две шкалы — одна переменная','Екі шкала — бір айнымалы'],['После решения каждой строки выпиши полученные интервалы времени или показателя. Затем пересекай их и ограничения модели. Если число циклов целое, округление нижней границы вверх выполняется только после точного решения, а верхней — вниз.','Әр жолды шешкен соң уақыт не көрсеткіш аралықтарын жаз. Кейін модель шектеулерімен қиылыстыр. Цикл саны бүтін болса, дәл шешімнен кейін төменгі шекті жоғары, жоғарғыны төмен дөңгелекте.']]
  ],[['Проверяй противоположные тенденции','Қарама-қарсы үрдістерді тексер'],['Отдельно подпиши «растёт» и «убывает» рядом с основаниями.','Негіздер жанына «өседі» және «кемиді» деп бөлек жаз.'],['Система может не иметь общего интервала.','Жүйеде ортақ аралық болмауы мүмкін.']],{title:['Окно между ростом и уменьшением','Өсу мен азаю арасындағы аралық'],problem:['В упрощённой модели за t дней A=2ᵗ должно быть не меньше 8, B=32·(1/2)ᵗ — не меньше 2. t≥0. Найди окно времени.','Жеңілдетілген модельде t күнде A=2ᵗ кемінде 8, B=32·(1/2)ᵗ кемінде 2 болуы тиіс. t≥0. Уақыт аралығын тап.'],steps:[['2ᵗ≥2³ даёт t≥3.','2ᵗ≥2³ теңсіздігі t≥3 береді.'],['(1/2)ᵗ≥1/16=(1/2)⁴ даёт t≤4.','(1/2)ᵗ≥1/16=(1/2)⁴ теңсіздігі t≤4 береді.'],['Общее окно 3≤t≤4 дня.','Ортақ аралық 3≤t≤4 күн.']],answer:'t ∈ [3;4] дня',answerText:['t ∈ [3;4] дня','t ∈ [3;4] күн'],connection:['Два противоположных процесса могут задавать ограниченное окно.','Қарама-қарсы екі үдеріс шектеулі аралық беруі мүмкін.'],takeaway:['Меняющийся знак связан с основанием, а не с желаемым ответом.','Таңбаның өзгеруі қажетті жауапқа емес, негізге байланысты.']},'32*(1/2)**4',2),
  'log-inequality-systems':e(['В логарифмической системе сначала пересекаются области допустимых значений, потом решения сравнений. Пропуск первой части может добавить невозможные значения.','Логарифмдік жүйеде алдымен мүмкін мәндер облыстары, кейін салыстыру шешімдері қиылысады. Бірінші қадамды өткізу мүмкін емес мәндерді қосуы ықтимал.'],[
    [['Каждый аргумент положителен','Әр аргумент оң'],['Для log₂(x−1) и log₂(9−x) общая ОДЗ: x>1 и x<9. Основание должно быть положительным и не равняться единице. Основания меньше единицы меняют знак при переходе к аргументам.','log₂(x−1), log₂(9−x) үшін ортақ ММО: x>1, x<9. Негіз оң және бірден өзгеше болуы тиіс. Бірден кіші негіз аргументке өткенде таңбаны өзгертеді.']],
    [['Собери все ограничения','Барлық шектеуді жина'],['Записывай каждую строку с её ОДЗ, даже если часть условий позже окажется лишней. Строгая граница аргумента не становится разрешённой от нестрогого знака логарифмического неравенства. Проверь полученный интервал в обеих исходных строках.','Әр жолды ММО-мен жаз, кейбір шарттар кейін артық болса да. Логарифм теңсіздігі қатаң емес болғанымен, аргументтің қатаң шекарасы рұқсат болмайды. Нәтиже аралығын екі бастапқы жолда тексер.']]
  ],[['Начни с простых границ','Қарапайым шектерден баста'],['log₂u≥1 означает u≥2, но только потому, что основание 2>1.','log₂u≥1 — u≥2, бірақ тек 2>1 болғандықтан.'],['Не сравнивай показатели без учёта основания и ОДЗ.','Негіз бен ММО-ны ескермей көрсеткіштерді салыстырма.']],{title:['Два нормированных запаса','Екі нормаланған қор'],problem:['Учебная модель задаёт запасы x−1 и 9−x. Требуется log₂(x−1)≥1 и log₂(9−x)≥1. Найди x.','Оқу моделі қорларды x−1, 9−x деп береді. log₂(x−1)≥1 және log₂(9−x)≥1 керек. x-ті тап.'],steps:[['ОДЗ 1<x<9.','ММО 1<x<9.'],['Основание 2>1: x−1≥2 и 9−x≥2.','Негіз 2>1: x−1≥2 және 9−x≥2.'],['Получаем x≥3 и x≤7; итог [3;7] внутри ОДЗ.','x≥3, x≤7; қорытынды [3;7] ММО ішінде.']],answer:'x ∈ [3;7]',connection:['Положительные безразмерные запасы моделируют две конкурирующие потребности.','Оң өлшемсіз қорлар екі бәсекелес қажеттілікті модельдейді.'],takeaway:['Все строки системы должны выполняться одновременно.','Жүйенің барлық жолы бір уақытта орындалуы тиіс.']},'9-2',7),
  'space-relations':e(['В пространстве прямые могут не пересекаться и при этом не быть параллельными. Нужно выяснить, лежат ли они в одной плоскости.','Кеңістікте түзулер қиылыспай, параллель де болмауы мүмкін. Олардың бір жазықтықта жататынын анықтау керек.'],[
    [['Три положения прямых','Түзулердің үш орналасуы'],['Пересекающиеся прямые имеют общую точку. Параллельные лежат в одной плоскости и не пересекаются. Скрещивающиеся не лежат в одной плоскости. В перспективном рисунке линии могут выглядеть пересекающимися, хотя их точки находятся на разной высоте.','Қиылысатын түзулердің ортақ нүктесі бар. Параллель түзулер бір жазықтықта жатып, қиылыспайды. Айқас түзулер бір жазықтықта жатпайды. Перспективада биіктіктері әртүрлі түзулер қиылысқандай көрінуі мүмкін.']],
    [['Перпендикулярность плоскости','Жазықтыққа перпендикулярлық'],['Чтобы доказать, что прямая перпендикулярна плоскости, достаточно показать её перпендикулярность двум пересекающимся прямым этой плоскости. Перпендикулярность одной линии недостаточна. Расстояние до плоскости измеряется по перпендикуляру, а не по любой наклонной.','Түзудің жазықтыққа перпендикулярлығын дәлелдеу үшін сол жазықтықтағы екі қиылысатын түзуге перпендикуляр екенін көрсету жеткілікті. Бір түзу жеткіліксіз. Жазықтыққа арақашықтық көлбеумен емес, перпендикулярмен өлшенеді.']]
  ],[['Используй имена рёбер','Қыр атауларын қолдан'],['В кубе подпиши вершины и назови конкретные рёбра: слова «левая линия» неоднозначны при повороте.','Куб төбелерін белгілеп, нақты қырларды ата: бұрғанда «сол жақ сызық» екіұшты.'],['Видимый угол на рисунке не равен автоматически пространственному углу.','Суреттегі көрінетін бұрыш кеңістіктегі бұрышқа автоматты түрде тең емес.']],{title:['Трос над полом','Еден үстіндегі арқан'],problem:['В модели точка крепления находится на 4 м выше пола. Наклонный трос идёт к точке пола в 3 м от основания вертикали. Найди длину троса.','Модельде бекіту нүктесі еденнен 4 м жоғары. Көлбеу арқан вертикаль табанынан 3 м жердегі еден нүктесіне барады. Арқан ұзындығын тап.'],steps:[['Вертикаль перпендикулярна полу, значит и линии пола к якорю.','Вертикаль еденге, демек якорьге баратын еден сызығына перпендикуляр.'],['Получаем прямоугольный треугольник с катетами 4 и 3 м.','Катеттері 4 және 3 м тікбұрышты үшбұрыш аламыз.'],['Длина троса √(4²+3²)=5 м.','Арқан ұзындығы √(4²+3²)=5 м.']],answer:'5 м',connection:['Расстояние до пола 4 м и длина наклонного троса 5 м — разные величины.','Еденге арақашықтық 4 м, көлбеу арқан ұзындығы 5 м — бөлек шамалар.'],takeaway:['Сначала докажи прямой угол, затем применяй Пифагора.','Алдымен тік бұрышты негізде, кейін Пифагорды қолдан.']},'4**2+3**2',25),
  'sections':e(['Сечение — фигура, полученная пересечением тела с плоскостью. Это не тень тела и не обязательно одна из его граней.','Қима — денені жазықтықпен қиғанда алынған фигура. Ол дененің көлеңкесі емес және міндетті түрде жақтарының бірі емес.'],[
    [['Строй внутри каждой грани','Әр жақ ішінде сал'],['Плоскость пересекает грань многогранника по прямой. Соедини две известные точки только тогда, когда они лежат на одной грани. Продолжай линию до рёбер и переноси найденные точки на соседнюю грань. Три неколлинеарные точки задают плоскость сечения.','Жазықтық көпжақ жағын түзу бойымен қияды. Екі белгілі нүктені бір жақта жатса ғана қос. Сызықты қырға дейін созып, табылған нүктені көрші жаққа көшір. Бір түзуде жатпайтын үш нүкте қима жазықтығын анықтайды.']],
    [['Замкни контур','Контурды тұйықта'],['Все стороны сечения должны лежать на гранях и образовывать замкнутый многоугольник. В параллельных гранях линии одной секущей плоскости параллельны. После построения проверь форму: изображённый наклон не означает, что угол в сечении острый.','Қима қабырғалары жақтарда жатып, тұйық көпбұрыш құруы керек. Параллель жақтардағы бір қима жазықтығының сызықтары параллель. Құрылыс соңында пішінді тексер: суреттегі көлбеулік қима бұрышы сүйір дегенді білдірмейді.']]
  ],[['Начни с грани с двумя точками','Екі нүктесі бар жақтан баста'],['На этой грани линия сечения определяется сразу. Затем двигайся по соседним граням.','Осы жақта қима сызығы бірден анықталады. Кейін көрші жақтарға өт.'],['Произвольное соединение всех видимых точек даёт неверное сечение.','Көрінетін нүктелерді ретсіз қосу қате қима береді.']],{title:['Разрез прямоугольной упаковки','Тікбұрышты қаптаманы қию'],problem:['Коробка имеет основание 3 × 4 см и высоту 6 см. Вертикальная секущая плоскость проходит через диагональ основания. Найди площадь сечения.','Қорап табаны 3 × 4 см, биіктігі 6 см. Тік қима жазықтығы табан диагоналінен өтеді. Қима ауданын тап.'],steps:[['Сечение — прямоугольник с высотой 6 см.','Қима — биіктігі 6 см тіктөртбұрыш.'],['Вторая сторона — диагональ основания √(3²+4²)=5 см.','Екінші қабырға — табан диагоналі √(3²+4²)=5 см.'],['Площадь 5·6=30 см².','Аудан 5·6=30 см².']],answer:'30 см²',connection:['Плоскость разреза определяет новую плоскую фигуру внутри тела.','Қию жазықтығы дене ішінде жаңа жазық фигура береді.'],takeaway:['Размеры сечения нужно сначала вывести из геометрии тела.','Қима өлшемдерін алдымен дене геометриясынан шығар.']},'5*6',30),
  'prisms':e(['Призма имеет два равных параллельных основания, соединённых боковыми гранями. В прямой призме боковые рёбра перпендикулярны основаниям.','Призманың екі тең параллель табаны бүйір жақтармен қосылады. Тік призмада бүйір қырлар табандарға перпендикуляр.'],[
    [['Основание выбирает формулу','Табан формуланы анықтайды'],['Основанием может быть треугольник, четырёхугольник или другой многоугольник. Сначала вычисли его площадь Sₒ, затем объём V=Sₒh. Высота h — перпендикулярное расстояние между основаниями; в наклонной призме она не равна боковому ребру.','Табан үшбұрыш, төртбұрыш не басқа көпбұрыш болуы мүмкін. Алдымен Sₒ ауданын, кейін V=Sₒh көлемін тап. h — табандар арасындағы перпендикуляр арақашықтық; көлбеу призмада ол бүйір қырға тең емес.']],
    [['Боковая поверхность','Бүйір бет'],['У прямой призмы боковые грани — прямоугольники высоты h. Их суммарная площадь Pₒh, где Pₒ — периметр основания. Полная поверхность S=Pₒh+2Sₒ. Для наклонной призмы эта короткая формула боковой площади обычно не подходит.','Тік призманың бүйір жақтары биіктігі h тіктөртбұрыштар. Қосынды ауданы Pₒh, мұнда Pₒ — табан периметрі. Толық бет S=Pₒh+2Sₒ. Көлбеу призмаға бұл қысқа бүйір аудан формуласы әдетте жарамайды.']]
  ],[['Проверь прямоту призмы','Призманың тіктігін тексер'],['Один и тот же h используется для объёма, но формула Pₒh для поверхности требует прямой призмы.','Көлемге h қолданылады, ал бетке Pₒh формуласы тік призманы талап етеді.'],['Не путай периметр основания с его площадью.','Табан периметрін оның ауданымен шатастырма.']],{title:['Треугольная упаковка','Үшбұрышты қаптама'],problem:['Модель упаковки — прямая призма длиной 10 см. Основание — прямоугольный треугольник с катетами 3 и 4 см. Найди объём.','Қаптама моделі — ұзындығы 10 см тік призма. Табаны катеттері 3 және 4 см тікбұрышты үшбұрыш. Көлемін тап.'],steps:[['Площадь треугольного основания 3·4/2=6 см².','Үшбұрыш табан ауданы 3·4/2=6 см².'],['Высота призмы — её длина 10 см.','Призма биіктігі — оның 10 см ұзындығы.'],['Объём 6·10=60 см³.','Көлем 6·10=60 см³.']],answer:'60 см³',connection:['Призма описывает упаковку с одинаковым сечением по длине.','Призма ұзындығы бойымен қимасы бірдей қаптаманы сипаттайды.'],takeaway:['В треугольной упаковке сначала считаем площадь треугольника.','Үшбұрышты қаптамада алдымен үшбұрыш ауданын есептейміз.']},'3*4/2*10',60),
  'pyramids':e(['Все боковые грани пирамиды сходятся в одной вершине. Объём такой фигуры составляет треть объёма призмы с тем же основанием и высотой.','Пирамиданың барлық бүйір жақтары бір төбеде кездеседі. Көлемі табаны мен биіктігі бірдей призманың үштен біріне тең.'],[
    [['Высота не равна ребру','Биіктік қырға тең емес'],['Высота пирамиды — перпендикуляр от вершины к плоскости основания. Боковое ребро идёт к вершине основания, апофема правильной пирамиды — к середине стороны основания по боковой грани. Эти отрезки обычно имеют разные длины.','Пирамида биіктігі — төбеден табан жазықтығына перпендикуляр. Бүйір қыр табан төбесіне, дұрыс пирамиданың апофемасы бүйір жақ бойымен табан қабырғасының ортасына барады. Ұзындықтары әдетте әртүрлі.']],
    [['Две площади','Екі аудан'],['Для объёма используй Sₒh/3. Для правильной пирамиды боковая площадь равна Pₒl/2, где l — апофема. Полная площадь добавляет основание. Если пирамида не правильная, боковые треугольники могут требовать отдельного вычисления.','Көлем үшін Sₒh/3 қолдан. Дұрыс пирамиданың бүйір ауданы Pₒl/2, l — апофема. Толық ауданға табанды қос. Пирамида дұрыс болмаса, бүйір үшбұрыштарды жеке есептеу қажет болуы мүмкін.']]
  ],[['Нарисуй три разные высоты','Үш кесіндіні ажыратып сал'],['Подпиши вертикальную высоту, апофему и ребро разными буквами до подстановки.','Қояр алдында тік биіктік, апофема және қырды әртүрлі әріппен белгіле.'],['Формула правильной пирамиды не переносится без проверки симметрии.','Дұрыс пирамида формуласы симметрияны тексермей қолданылмайды.']],{title:['Пирамидальная декоративная форма','Пирамида пішінді сәндік қалып'],problem:['Модель формы — пирамида с квадратным основанием 6 × 6 см и перпендикулярной высотой 9 см. Найди внутренний объём.','Қалып моделі — табаны 6 × 6 см шаршы, перпендикуляр биіктігі 9 см пирамида. Ішкі көлемін тап.'],steps:[['Площадь основания 6²=36 см².','Табан ауданы 6²=36 см².'],['Призма с теми же размерами имела бы 36·9=324 см³.','Осы өлшемдегі призма көлемі 36·9=324 см³ болар еді.'],['Пирамида: 324/3=108 см³.','Пирамида: 324/3=108 см³.']],answer:'108 см³',connection:['Форма с сужением к одной вершине требует коэффициента 1/3.','Бір төбеге тарылатын пішін 1/3 коэффициентін қажет етеді.'],takeaway:['Для объёма берётся перпендикулярная высота, не наклонный край.','Көлемге көлбеу қыр емес, перпендикуляр биіктік алынады.']},'6**2*9/3',108),
  'cylinders':e(['Цилиндр состоит из одинаковых круговых слоёв. Развёрнутая боковая поверхность становится прямоугольником.','Цилиндр бірдей дөңгелек қабаттардан тұрады. Жазылған бүйір бет тіктөртбұрыш болады.'],[
    [['Объём через основание','Табан арқылы көлем'],['Для прямого кругового цилиндра V=πr²h. Радиус r измеряется от центра основания до его края, h — расстояние между основаниями. Диаметр нужно разделить на два. В задаче о жидкости берём внутренний радиус и высоту заполнения.','Тік дөңгелек цилиндр үшін V=πr²h. r табан центрінен шетіне дейін, h табандар арасындағы арақашықтық. Диаметрді екіге бөл. Сұйыққа ішкі радиус пен толу биіктігін ал.']],
    [['Прямоугольник развёртки','Жазба тіктөртбұрышы'],['Одна сторона развёртки равна высоте h, другая — длине окружности 2πr. Поэтому боковая площадь 2πrh. Полная поверхность добавляет два круга: 2πrh+2πr². Открытый сосуд включает лишь одно дно и не включает крышку.','Жазбаның бір қабырғасы h, екіншісі шеңбер ұзындығы 2πr. Сондықтан бүйір аудан 2πrh. Толық бетке екі дөңгелек қосылады: 2πrh+2πr². Ашық ыдыста бір түбі бар, қақпақ жоқ.']]
  ],[['Этикетка — боковая площадь','Жапсырма — бүйір аудан'],['Если требуется только прямоугольная этикетка вокруг банки, основания не добавляй.','Тек банканы айналдыратын жапсырма керек болса, табандарды қоспа.'],['Нахлёст этикетки и припуски нужны лишь при отдельном условии.','Жапсырманың қабаттасуы мен қосымша қоры бөлек шартпен беріледі.']],{title:['Этикетка цилиндрической банки','Цилиндр банкі жапсырмасы'],problem:['Радиус банки 3 см, высота этикетки 8 см. Найди площадь этикетки без нахлёста.','Банкі радиусы 3 см, жапсырма биіктігі 8 см. Қабаттасусыз жапсырма ауданын тап.'],steps:[['Длина окружности банки 2π·3=6π см.','Банкі шеңбер ұзындығы 2π·3=6π см.'],['Этикетка разворачивается в прямоугольник 6π × 8 см.','Жапсырма 6π × 8 см тіктөртбұрыш болып жазылады.'],['Площадь 48π см².','Аудан 48π см².']],answer:'48π см²',connection:['Развёртка связывает поверхность тела с плоской площадью.','Жазба дене бетін жазық ауданмен байланыстырады.'],takeaway:['Для этикетки считаем боковую поверхность, для жидкости — объём.','Жапсырмаға бүйір бет, сұйыққа көлем есептеледі.']},'2*3*8',48),
  'cones':e(['Конус сужается от круглого основания к вершине. Его высота, радиус и образующая связаны прямоугольным треугольником.','Конус дөңгелек табаннан төбеге тарылады. Биіктігі, радиусы және жасаушысы тікбұрышты үшбұрышпен байланысты.'],[
    [['Три важных отрезка','Үш маңызды кесінді'],['У прямого кругового конуса высота h идёт к центру основания перпендикулярно ему. Радиус r лежит в основании. Образующая l идёт по боковой поверхности от вершины до окружности; l²=r²+h². Образующая не равна высоте.','Тік дөңгелек конустың h биіктігі табан центріне перпендикуляр барады. r радиусы табанда жатады. l жасаушысы төбеден шеңберге бүйір бетпен барады; l²=r²+h². Жасаушы биіктікке тең емес.']],
    [['Объём и оболочка','Көлем мен қабық'],['Объём V=πr²h/3 использует вертикальную высоту. Боковая площадь Sб=πrl использует образующую. Полная площадь добавляет πr². Модель тонкого бумажного колпака без дна требует только боковой площади; толщина бумаги отдельно не учитывается.','V=πr²h/3 көлемі тік биіктікті пайдаланады. Sб=πrl бүйір ауданы жасаушыны пайдаланады. Толық ауданға πr² қосылады. Түбі жоқ жұқа қағаз қалпаққа тек бүйір аудан қажет.']]
  ],[['Пифагор до площади','Ауданға дейін Пифагор'],['Если даны r и h, сначала найди l, а потом считай боковую площадь.','r және h берілсе, алдымен l-ді тауып, кейін бүйір ауданды есепте.'],['Не подставляй h вместо l в формулу πrl.','πrl формуласына l орнына h қойма.']],{title:['Бумажный колпак','Қағаз қалпақ'],problem:['Конусообразный колпак без дна имеет радиус 3 см и высоту 4 см. Найди площадь бумаги без припуска.','Түбі жоқ конус қалпақ радиусы 3 см, биіктігі 4 см. Қорсыз қағаз ауданын тап.'],steps:[['Образующая l=√(3²+4²)=5 см.','Жасаушы l=√(3²+4²)=5 см.'],['Нужно только боковое покрытие.','Тек бүйір жабын керек.'],['S=π·3·5=15π см².','S=π·3·5=15π см².']],answer:'15π см²',connection:['Поверхность колпака отличается от площади его круглого отверстия.','Қалпақ беті дөңгелек тесігінің ауданынан өзгеше.'],takeaway:['Сначала выясни, есть ли у предмета дно.','Алдымен заттың түбі бар-жоғын анықта.']},'3*5',15),
  'spheres':e(['Сфера — поверхность, шар — тело внутри неё. Все точки сферы находятся на одинаковом расстоянии r от центра.','Сфера — бет, шар — оның ішіндегі дене. Сфераның барлық нүктесі центрден бірдей r қашықтықта.'],[
    [['Поверхность и объём','Бет пен көлем'],['Площадь сферы равна 4πr², объём шара — 4πr³/3. Удвоение радиуса увеличивает площадь в четыре раза, объём — в восемь. Не используй площадь круга πr² вместо площади сферической оболочки.','Сфера ауданы 4πr², шар көлемі 4πr³/3. Радиус екі есе артса, аудан төрт, көлем сегіз есе артады. Сфера қабығына дөңгелек πr² ауданын қолданба.']],
    [['Круг сечения','Қима дөңгелегі'],['Плоскость пересекает шар по кругу. Если расстояние плоскости от центра d меньше r, радиус сечения ρ удовлетворяет ρ²=r²−d². Наибольшее сечение проходит через центр. При d=r плоскость касается сферы в одной точке.','Жазықтық шарды дөңгелекпен қияды. Центрден жазықтыққа d арақашықтығы r-ден кіші болса, қима радиусы ρ үшін ρ²=r²−d². Ең үлкен қима центрден өтеді. d=r болса, жазықтық сфераға бір нүктеде жанасады.']]
  ],[['Диаметр пополам','Диаметрді екіге бөл'],['Даже если мяч измерили линейкой поперёк, в формулы нужен радиус — половина диаметра.','Допты көлденең өлшесе де, формулаға радиус — диаметрдің жартысы керек.'],['Формулы относятся к идеальной сфере; швы и толщина оболочки — отдельные детали модели.','Формулалар идеал сфераға арналған; тігіс пен қабық қалыңдығы модельдің бөлек бөлшектері.']],{title:['Покрытие декоративного шара','Сәндік шарды жабу'],problem:['Идеальный декоративный шар имеет диаметр 10 см. Найди площадь покрытия без запаса.','Идеал сәндік шардың диаметрі 10 см. Қорсыз жабын ауданын тап.'],steps:[['Радиус r=10/2=5 см.','Радиус r=10/2=5 см.'],['Нужна площадь сферы, не объём.','Сфера ауданы керек, көлем емес.'],['S=4π·5²=100π см².','S=4π·5²=100π см².']],answer:'100π см²',connection:['Покраска идеального шара требует площадь его внешней оболочки.','Идеал шарды бояуға сыртқы қабық ауданы қажет.'],takeaway:['Степень единицы в ответе должна быть второй для покрытия.','Жабын жауабындағы бірлік дәрежесі екі болуы керек.']},'4*(10/2)**2',100),
  'plane-transformations':e(['Геометрическое преобразование задаёт правило, куда переходит каждая точка. Образ фигуры строят по этому правилу, а не по визуальному сходству.','Геометриялық түрлендіру әр нүктенің қайда өтетінін береді. Фигура бейнесі сыртқы ұқсастықпен емес, осы ережемен салынады.'],[
    [['Движения сохраняют размеры','Қозғалыстар өлшемді сақтайды'],['Перенос добавляет одинаковый вектор всем точкам. Поворот сохраняет расстояние до центра и задаёт одинаковый угол. Отражение относительно оси переносит точку на другую сторону на равное перпендикулярное расстояние. Эти преобразования сохраняют длины и углы.','Параллель көшіру барлық нүктеге бірдей вектор қосады. Бұру центрге арақашықтықты сақтап, бірдей бұрыш береді. Осьтік симметрия нүктені екінші жаққа бірдей перпендикуляр қашықтыққа көшіреді. Бұлар ұзындық пен бұрышты сақтайды.']],
    [['Увеличение — другое правило','Үлкейту — басқа ереже'],['Гомотетия с центром O и коэффициентом k умножает вектор OP на k. Длины меняются в |k| раз, площади в k² раз. При k<0 точка оказывается по противоположную сторону центра. Масштабирование не является движением, если |k|≠1.','O центрлі, k коэффициентті гомотетия OP векторын k-ға көбейтеді. Ұзындық |k| есе, аудан k² есе өзгереді. k<0 болса, нүкте центрдің қарама-қарсы жағына өтеді. |k|≠1 болса, масштабтау қозғалыс емес.']]
  ],[['Проверь одну опорную точку','Бір тірек нүктені тексер'],['Для отражения в оси Oy меняется знак x, но y сохраняется; для Ox наоборот.','Oy осіне шағылдырғанда x таңбасы өзгереді, y сақталады; Ox үшін керісінше.'],['Порядок двух преобразований может менять результат.','Екі түрлендірудің реті нәтижені өзгертуі мүмкін.']],{title:['Перенос значка на экране','Экрандағы белгіні жылжыту'],problem:['В условной координатной сетке значок стоит в A(2;3). Его переносят на вектор (4;−1), затем отражают в оси Oy. Где он окажется?','Шартты координата торында белгі A(2;3)-те. Оны (4;−1) векторына көшіріп, кейін Oy осіне шағылдырады. Соңғы орны қандай?'],steps:[['После переноса: (2+4;3−1)=(6;2).','Көшіруден кейін: (2+4;3−1)=(6;2).'],['При отражении в Oy x меняет знак.','Oy-ге шағылғанда x таңбасы өзгереді.'],['Итоговая точка (−6;2).','Соңғы нүкте (−6;2).']],answer:'(−6;2)',connection:['Координатные преобразования используются при размещении изображений.','Координаталық түрлендірулер кескіндерді орналастыруда қолданылады.'],takeaway:['Выполняй действия в заданном порядке.','Әрекеттерді берілген ретпен орында.']},'-(2+4)',-6),
  'space-distance':e(['В пространстве кратчайшее расстояние от точки до плоскости проходит по перпендикуляру. Расстояние между двумя точками учитывает все три координаты.','Кеңістікте нүктеден жазықтыққа ең қысқа қашықтық перпендикулярмен өтеді. Екі нүктенің арақашықтығы үш координатаны да ескереді.'],[
    [['От точки до точки','Нүктеден нүктеге'],['Для координат сначала найди три разности Δx, Δy, Δz. Тогда d=√(Δx²+Δy²+Δz²). Формула получается двукратным применением Пифагора. Знаки разностей исчезают при квадратировании, поэтому перестановка точек не меняет расстояние.','Алдымен Δx, Δy, Δz үш айырманы тап. d=√(Δx²+Δy²+Δz²). Формула Пифагорды екі рет қолданудан шығады. Квадраттағанда таңбалар жоғалады, сондықтан нүктелер ретін ауыстыру қашықтықты өзгертпейді.']],
    [['От точки до плоскости','Нүктеден жазықтыққа'],['Для плоскости Ax+By+Cz+D=0 расстояние от (x₀;y₀;z₀) равно |Ax₀+By₀+Cz₀+D|/√(A²+B²+C²). Коэффициенты A,B,C не могут все быть нулевыми. Модуль обеспечивает неотрицательность, знаменатель нормирует размер нормали.','Ax+By+Cz+D=0 жазықтығына (x₀;y₀;z₀) нүктесінен қашықтық |Ax₀+By₀+Cz₀+D|/√(A²+B²+C²). A,B,C бәрі нөл болмауы тиіс. Модуль теріс емес нәтижені, бөлім нормаль өлшемін түзетуді береді.']]
  ],[['Разности до квадратов','Квадратқа дейін айырмалар'],['Запиши разности отдельной строкой, чтобы не возвести в квадрат исходные координаты вместо разностей.','Бастапқы координаталарды қателесіп квадраттамау үшін айырмаларды бөлек жолға жаз.'],['Координаты должны быть в одной системе и единице.','Координаталар бір жүйе мен бірлікте болуы керек.']],{title:['Прямой путь дрона','Дронның тура жолы'],problem:['В учебной модели дрон летит прямо из A(1;2;1) в B(3;5;7), координаты в метрах. Найди расстояние.','Оқу моделінде дрон A(1;2;1)-ден B(3;5;7)-ге тура ұшады, координаталар метрмен. Қашықтықты тап.'],steps:[['Разности: 2,3,6 м.','Айырмалар: 2,3,6 м.'],['Квадрат расстояния: 2²+3²+6²=49 м².','Қашықтық квадраты: 2²+3²+6²=49 м².'],['d=7 м; препятствия и траектория обхода в модель не входят.','d=7 м; кедергілер мен айналып ұшу бұл модельге кірмейді.']],answer:'7 м',connection:['Три координаты позволяют измерить прямое пространственное перемещение.','Үш координата кеңістіктегі тура орын ауыстыруды өлшейді.'],takeaway:['Реальная длина маршрута может превышать прямое расстояние.','Нақты маршрут тура қашықтықтан ұзын болуы мүмкін.']},'(3-1)**2+(5-2)**2+(7-1)**2',49),
  'space-transformations':e(['Пространственное преобразование действует на каждую точку тела. При переносе и вращении тело меняет положение, но не размеры.','Кеңістік түрлендіруі дененің әр нүктесіне әсер етеді. Көшіру мен бұру дене орнын өзгертеді, өлшемін өзгертпейді.'],[
    [['Три координаты переноса','Көшірудің үш координатасы'],['Перенос на вектор (a;b;c) превращает (x;y;z) в (x+a;y+b;z+c). Отражение относительно плоскости Oxy меняет знак z, оставляя x,y прежними. Центральная симметрия относительно начала меняет знаки всех трёх координат.','(a;b;c) векторына көшіру (x;y;z)-ті (x+a;y+b;z+c)-ке айналдырады. Oxy жазықтығына симметрия z таңбасын ғана өзгертеді. Координата басына қатысты центрлік симметрия үшеуінің де таңбасын өзгертеді.']],
    [['Ось вращения','Бұрылу осі'],['Вращение вокруг Oz сохраняет z. Для поворота на 90° против часовой стрелки при взгляде со стороны положительного Oz правило: (x;y;z)→(−y;x;z). Укажи направление взгляда: без него слова «по часовой стрелке» в пространстве неоднозначны.','Oz бойымен бұру z-ті сақтайды. Оң Oz жағынан қарағанда сағат тіліне қарсы 90° бұру: (x;y;z)→(−y;x;z). Қарау бағытын ата: онсыз кеңістікте «сағат тілімен» сөзі екіұшты.']]
  ],[['Контроль длины','Ұзындықты бақылау'],['При повороте вокруг Oz проверь, что x²+y² осталось прежним и z не изменился.','Oz бойымен бұрғанда x²+y² өзгермегенін және z сақталғанын тексер.'],['Масштабирование меняет размеры и не относится к движениям при |k|≠1.','|k|≠1 кезінде масштабтау өлшемді өзгертіп, қозғалыс болмайды.']],{title:['Поворот точки 3D-модели','3D-модель нүктесін бұру'],problem:['Точку P(2;1;3) вращают вокруг Oz на 90° против часовой стрелки, глядя с положительного направления Oz. Найди новый образ.','P(2;1;3) нүктесін оң Oz жағынан қарап, Oz бойымен сағат тіліне қарсы 90° бұрады. Жаңа бейнесін тап.'],steps:[['При этом повороте x′=−y, y′=x.','Бұл бұруда x′=−y, y′=x.'],['Получаем x′=−1, y′=2; z′=3 сохраняется.','x′=−1, y′=2; z′=3 сақталады.'],['Проверка радиуса: 2²+1²=(−1)²+2²=5.','Радиус тексеруі: 2²+1²=(−1)²+2²=5.']],answer:'P′(−1;2;3)',connection:['Такое правило применяется к вершинам простой 3D-модели.','Бұл ереже қарапайым 3D-модель төбелеріне қолданылады.'],takeaway:['Для вращения нужно указать ось, угол и направление.','Бұру үшін ось, бұрыш және бағыт керек.']},'(-1)**2+2**2',5),
};

// A third authored explanation makes the reasoning checkable before practice.
const understandingChecks:Record<string,Pair> = {
  angles:['Если угол оказался больше 180°, уточни, требуется ли меньший угол между лучами или полный поворот. Обозначь известные углы дугами. Объясни словами, почему ты складываешь их или вычитаешь из 180°. Так действие не будет случайным подбором формулы.','Бұрыш 180°-тан үлкен шықса, сәулелер арасындағы кіші бұрыш па, толық бұрылу ма екенін анықта. Белгілі бұрыштарды доғамен белгіле. Неге қосатыныңды не 180°-тан азайтатыныңды сөзбен түсіндір: сонда амал кездейсоқ формула таңдауы болмайды.'],
  triangles:['После вычисления третьего угла сложи все три: должно получиться 180°. После нахождения стороны сравни её с суммой двух остальных. Для прямоугольного случая гипотенуза обязана быть длиннее каждого катета. Эти независимые проверки обнаруживают перепутанные обозначения и ошибку со знаком.','Үшінші бұрышты есептеген соң үшеуін қос: 180° шығуы тиіс. Қабырғаны тапқан соң оны қалған екеуінің қосындысымен салыстыр. Тікбұрышты жағдайда гипотенуза әр катеттен ұзын болуы керек. Бұл тәуелсіз тексерулер белгілеу және таңба қатесін табады.'],
  quadrilaterals:['Попроси себя объяснить каждое равенство на рисунке. Если сторона названа высотой, покажи её прямой угол с основанием. Если выбрана формула ромба, укажи равенство всех сторон. Название фигуры должно подтверждаться условием или доказанными свойствами, а не удобством вычислений.','Суреттегі әр теңдікті түсіндір. Қабырғаны биіктік десең, табанмен тік бұрышын көрсет. Ромб формуласын таңдасаң, барлық қабырға теңдігін ата. Фигура атауы есептеу ыңғайына емес, шартқа не дәлелденген қасиеттерге сүйенуі тиіс.'],
  circles:['Представь два круга, у второго радиус вдвое больше. Сравни ответы своей формулы: для длины должен получиться коэффициент два, для площади — четыре. Если результат изменился иначе, вероятно, перепутаны радиус с диаметром или первая степень радиуса со второй.','Екі дөңгелекті елестет, екіншісінің радиусы екі есе үлкен. Формулаңда ұзындық екі, аудан төрт есе өзгеруі тиіс. Өзгеше нәтиже болса, радиус пен диаметр не радиустың бірінші және екінші дәрежесі шатасқан болуы мүмкін.'],
  similarity:['Прежде чем составлять пропорцию, прочитай пары сторон вслух: маленькая высота соответствует большой высоте, маленькая тень — большой тени. Проверь, что коэффициент масштаба одинаков для обеих пар. Если нет, либо сопоставление неверно, либо фигуры не подобны в выбранной модели.','Пропорция алдында қабырға жұптарын ата: кіші биіктік үлкен биіктікке, кіші көлеңке үлкен көлеңкеге сәйкес. Екі жұптың масштаб коэффициенті бірдей екенін тексер. Сәйкес болмаса, жұптар қате не фигуралар модельде ұқсас емес.'],
  'plane-vectors':['Отрицательная координата не означает отрицательную длину вектора. Например, перемещение влево на три единицы даёт первую координату −3, но длину 3. Проверь результат сложения по конечной точке маршрута, а длину — по квадратам координат. Эти проверки отвечают на разные вопросы.','Теріс координата вектор ұзындығы теріс дегенді білдірмейді. Солға үш бірлік жүруде бірінші координата −3, ұзындық 3 болады. Қосындыны маршруттың соңғы нүктесімен, ұзындықты координаталар квадраттарымен тексер. Бұл тексерулер бөлек сұрақтарға жауап береді.'],
  solids:['Посчитай рёбра не только на видимой стороне, но и за ней. У коробки передняя и задняя рамки имеют по четыре ребра, ещё четыре соединяют их. Такой подсчёт объясняет число двенадцать и помогает восстановить скрытые линии на перспективном рисунке.','Қырларды көрінетін жақта ғана емес, артында да сана. Қораптың алдыңғы және артқы рамаларында төрттен қыр, оларды қосатын тағы төрт қыр бар. Бұл санау он екі санын түсіндіріп, перспективадағы жасырын сызықтарды қалпына келтіреді.'],
  volumes:['Проверь ответ грубой оценкой: если сосуд меньше куба с ребром один метр, его объём меньше одного кубического метра. Не прибавляй квадратные метры к кубическим. Ошибка единиц может изменить ответ в тысячу раз даже при правильных числах в формуле.','Жауапты жуық бағала: ыдыс қыры бір метр текшеден кіші болса, көлемі бір текше метрден аз. Квадрат метрді текше метрге қоспа. Формуладағы сандар дұрыс болса да, бірлік қатесі нәтижені мың есе өзгертуі мүмкін.'],
  'space-vectors':['Вычисли вектор BA тем же способом и сравни с AB: все три координаты должны поменять знаки. Длины при этом одинаковы. Если поменялась только одна координата, значит, при вычитании перепутан порядок точек. Этот приём работает независимо от рисунка тела.','BA векторын сол тәсілмен есептеп, AB-мен салыстыр: үш координата да таңбасын ауыстыруы тиіс. Ұзындықтар бірдей. Бір координата ғана өзгерсе, нүктелерді азайту реті шатасқан. Бұл тәсіл дене суретіне тәуелсіз орындалады.'],
  logic:['Сформулируй отрицание условия точно. Отрицание «все ученики пришли» — «хотя бы один не пришёл», а не «никто не пришёл». Между крайностями есть промежуточные случаи. Проверяя вывод, не заменяй исходное утверждение более сильным или более слабым без объяснения.','Шарттың терістеуін дәл айт. «Барлық оқушы келді» тұжырымының терістеуі — «кемінде біреуі келмеді», «ешкім келмеді» емес. Екі шектің арасында жағдайлар бар. Қорытындыны тексергенде бастапқы тұжырымды негізсіз күштірек не әлсізімен алмастырма.'],
  'word-models':['Попробуй объяснить каждое слагаемое уравнения словами. В примере 600x — стоимость детских билетов, а 1200(5−x) — взрослых. Если хотя бы один член не имеет понятного смысла или единицы не совпадают, модель нужно исправить до решения уравнения.','Теңдеудің әр қосылғышын сөзбен түсіндір. Мысалда 600x — бала билеттерінің, 1200(5−x) — ересектердің құны. Бір мүше түсініксіз болса не бірліктер сәйкес болмаса, теңдеуді шешпей тұрып модельді түзету керек.'],
  charts:['Прежде чем сравнивать два графика, проверь одинаковые интервалы времени и масштаб осей. Число за месяц нельзя напрямую сравнивать с числом за день. Если нужны средние значения за день, раздели месячные суммы на соответствующее число дней и только потом делай вывод.','Екі графикті салыстырмас бұрын уақыт аралықтары мен ось масштабтарын тексер. Айлық санды күндік санмен тікелей салыстырма. Күндік орташа керек болса, ай қосындысын тиісті күн санына бөліп, содан кейін ғана қорытынды жаса.'],
  statistics:['Среднее обязательно лежит между минимальным и максимальным значениями набора. Если получилось больше максимума, проверь сумму и число наблюдений. Медиану находят после сортировки, поэтому перестановка исходных данных не должна менять ответ. Размах не бывает отрицательным: он измеряет ширину диапазона.','Орташа жиынның ең кіші және ең үлкен мәні арасында жатады. Ең үлкеннен артық шықса, қосынды мен бақылау санын тексер. Медиана реттелген қатардан табылады, сондықтан деректердің орын ауыстыруы оны өзгертпейді. Құлаш теріс болмайды.'],
  probability:['Проверь, что полученная дробь от нуля до единицы. Если благоприятных исходов оказалось больше всех, что-то посчитано дважды. Неравновозможные исходы требуют иной модели: например, для разных вероятностей цветов недостаточно просто поделить число названий подходящих цветов на число всех цветов.','Нәтиже бөлшегі нөл мен бір арасында екенін тексер. Қолайлы нәтиже барлық нәтижеден көп болса, бірдеңе екі рет саналған. Тең мүмкін емес нәтижелерге басқа модель қажет: түс ықтималдықтары әртүрлі болса, атаулар санын жай бөлу жеткіліксіз.'],
  dependencies:['Подставь в модель ноль, если он разрешён, и объясни получившееся значение. В тарифе с начальной платой стоимость при нулевом расстоянии равна этой плате. В обратной пропорциональности ноль запрещён. Такой тест быстро отличает линейную модель от прямой и обратной пропорциональности.','Нөл рұқсат болса, оны модельге қойып, мәнін түсіндір. Бастапқы төлемі бар тарифте нөл қашықтықтың құны сол төлем. Кері пропорционалдықта нөл тыйым салынған. Бұл тексеру сызықтық модельді тура және кері пропорционалдықтан ажыратады.'],
  patterns:['Если рисунок строится по шагам, запиши отдельно первый элемент и правило добавления. Проверь второй и третий шаг вручную. Формула, которая совпала лишь с последним числом, ещё не объясняет закономерность. Для надёжного ответа нужно правило, которое воспроизводит все заданные шаги.','Сурет қадаммен құрылса, бірінші элемент пен қосу ережесін бөлек жаз. Екінші және үшінші қадамды қолмен тексер. Тек соңғы санға сай формула заңдылықты түсіндірмейді. Сенімді жауапқа барлық берілген қадамды қайталайтын ереже қажет.'],
  'geometric-logic':['Для подсчёта фигур придумай порядок, в котором каждая встречается ровно один раз: по верхнему левому углу, размеру или вершине. Отмечай уже учтённые фигуры. Такой порядок превращает наблюдение в аргумент полноты и защищает от двойного подсчёта одинаковой фигуры разными способами.','Фигураларды әрқайсысы дәл бір рет саналатындай ретпен сана: жоғарғы сол бұрыш, өлшем не төбе бойынша. Саналғандарын белгіле. Бұл рет бақылауды толықтық дәлеліне айналдырып, бір фигураны бірнеше тәсілмен қайталап санаудан қорғайды.'],
  'practical-area':['Посчитай площадь вторым способом, если фигура допускает и разбиение, и вычитание. Два одинаковых результата поддерживают правильность модели. Но оба способа должны покрывать именно нужную область. Участок под дверью, шкафом или нишей исключается только тогда, когда это явно сказано в условии.','Фигураны әрі бөлуге, әрі азайтуға болса, ауданды екінші тәсілмен есепте. Бірдей нәтиже модельді тексеруге көмектеседі. Екі тәсіл де қажетті аймақты қамтуы тиіс. Есік, шкаф не ойық астын тек шартта айтылса алып таста.'],
  surface:['Проверь, что у каждой посчитанной грани есть отдельное место на развёртке. Две противоположные грани одинаковы по площади, но каждая считается один раз. Когда тела склеены, общая граница исчезает снаружи с обеих сторон: нужно убрать две соответствующие площади, а не одну.','Саналған әр жақтың жазбада жеке орны барын тексер. Қарама-қарсы екі жақ ауданы тең, әрқайсысы бір рет саналады. Денелер желімделсе, ортақ шекара сырттан екі жағынан жоғалады: бір емес, екі сәйкес ауданды алып таста.'],
  'exponential-systems':['Если получены значения заменённых переменных, сначала проверь их сумму и разность, затем восстанови показатели и подставь исходные степени. Эти два этапа различают ошибку линейной системы и ошибку обратной замены. Например, значение u=8 означает показатель три при основании два, а не восемь.','Жаңа айнымалы мәндері шықса, алдымен қосындысы мен айырмасын тексер, кейін көрсеткіштерді тауып, бастапқы дәрежелерге қой. Екі кезең сызықтық жүйе қатесін кері алмастыру қатесінен ажыратады. Мысалы, негіз екі болса, u=8 көрсеткіштің үш екенін білдіреді.'],
  'log-systems':['После нахождения x и y вычисли каждый логарифм отдельно. Если сумма правильна, но разность имеет противоположный знак, вероятно, перепутан порядок переменных. В системе порядок важен: пары (8;4) и (4;8) удовлетворяют одинаковой сумме, но разным условиям на разность.','x пен y табылған соң әр логарифмді жеке есепте. Қосынды дұрыс, айырма таңбасы кері болса, айнымалылар реті шатасқан болуы мүмкін. Жүйеде рет маңызды: (8;4) пен (4;8) қосындысы бірдей, айырма шарттары әртүрлі.'],
  'irrational-systems':['Проверь именно исходные корни, а не только возведённые в квадрат уравнения. Значение √16 равно четырём, а не плюс-минус четырём. Знак ± возникает при решении x²=16, где неизвестно само x. Это различие объясняет, почему отрицательная обратная замена может оказаться лишней.','Тек квадратталған теңдеулерді емес, бастапқы түбірлерді тексер. √16 төртке тең, плюс-минус төрт емес. ± белгісі белгісіз x бар x²=16 теңдеуін шешкенде шығады. Бұл айырма теріс кері алмастырудың неге артық екенін түсіндіреді.'],
  'trig-systems':['Один и тот же угол должен удовлетворять обеим строкам. Нельзя объединить все корни первой строки со всеми корнями второй: нужна общая часть. На окружности отметь сначала допустимые точки синуса, затем оставь среди них только точки с нужным знаком и значением косинуса.','Бір бұрыш екі жолды да орындауы тиіс. Бірінші және екінші жол түбірлерін жай біріктірме: ортақ бөлік керек. Шеңберде алдымен синус нүктелерін, кейін солардың ішінен қажетті косинус таңбасы мен мәніне сай нүктелерді қалдыр.'],
  'exponential-inequalities':['Если время измеряется целыми периодами, проверь соседние целые значения у найденной границы. Для убывания запаса на пороге должно впервые выполниться ограничение, а предыдущий период ещё его нарушает. Эта проверка помогает отличить «через сколько впервые» от «в какие моменты вообще».','Уақыт бүтін кезеңмен өлшенсе, шекара жанындағы көршілес бүтін мәндерді тексер. Қор азайғанда шектеу шекарада алғаш орындалып, алдыңғы кезеңде бұзылуы тиіс. Бұл «алғаш қашан» мен «жалпы қай уақытта» сұрақтарын ажыратады.'],
  'log-inequalities':['Выбери точку внутри итогового интервала и вычисли знак аргумента. Затем проверь точку за границей. Если обе подходят исходному сравнению, вероятно, неверно изменён знак или забыта дополнительная часть решения. Конец, где аргумент обращается в ноль, исключён при любом знаке сравнения.','Соңғы аралық ішінен нүкте алып, аргумент таңбасын есепте. Кейін шекара сыртындағы нүктені тексер. Екеуі де бастапқы салыстыруға сай болса, таңба қате не шешімнің бөлігі ұмытылған. Аргумент нөл болатын ұш кез келген салыстыруда алынады.'],
  'irrational-inequalities':['Для квадратного корня значение подкоренного выражения может быть нулём. Но если корень стоит в знаменателе, ноль уже запрещён. Сравни √x и 1/√x: первая запись требует x≥0, вторая x>0. Так расположение одного и того же выражения меняет допустимую область.','Квадрат түбірдің асты нөл болуы мүмкін. Бірақ түбір бөлімде болса, нөл тыйым салынады. √x пен 1/√x-ті салыстыр: біріншісі x≥0, екіншісі x>0 талап етеді. Бір өрнектің орны мүмкін облысты өзгертеді.'],
  'trig-inequalities':['На выбранной дуге возьми знакомый угол, например 90° для синуса. Он должен удовлетворять неравенству. Проверь и точку вне дуги. Если интервал пересекает начало оборота, его удобно записать двумя частями в одном периоде, а затем дать общий ответ с повторением.','Таңдалған доғадан таныс бұрыш, мысалы синусқа 90° ал. Ол теңсіздікті орындауы тиіс. Доға сыртындағы нүктені де тексер. Аралық айналым басын кессе, бір периодта екі бөлікпен жазып, кейін қайталанатын жалпы жауап бер.'],
  'linear-inequality-systems':['Представь ученика, который проверяет конкретный ответ, например пять тетрадей. Он должен удовлетворять каждой строке системы. Проверка одной строки недостаточна. Если границы совпали, единственная точка остаётся только тогда, когда обе границы нестрогие; хотя бы одна строгая делает пересечение пустым.','Нақты жауапты, мысалы бес дәптерді тексерген оқушыны елестет. Ол жүйенің әр жолын орындауы керек. Бір жол жеткіліксіз. Шектер бірдей болса, екі шекара да қатаң емес болғанда ғана жалғыз нүкте қалады; бір қатаң шекара қиылысуды бос етеді.'],
  'rational-inequality-systems':['Для каждой запрещённой точки выясни, из какого знаменателя она появилась. Если дробь сокращается, исходная запись всё равно не определена в этой точке. На прямой используй отдельную отметку запрета. Это особенно важно, когда нуль числителя и знаменателя случайно совпадает при преобразовании.','Әр тыйым нүктенің қай бөлімнен шыққанын анықта. Бөлшек қысқарса да, бастапқы жазба сол нүктеде анықталмайды. Осьте бөлек тыйым белгісін қой. Бұл түрлендіруде алым мен бөлім нөлдері кездейсоқ сәйкес келгенде маңызды.'],
  'nonlinear-inequality-systems':['Проверь корни подстановкой в квадратный многочлен: результат должен быть нулём. Затем возьми одну точку между ними и одну снаружи. Знаки подтвердят расположение интервалов. После пересечения со второй строкой снова проверь крайние точки: одна граница может прийти из другого условия.','Түбірлерді квадрат көпмүшеге қой: нәтиже нөл болуы тиіс. Кейін олардың арасынан және сыртынан бір нүкте ал. Таңбалар аралықтарды растайды. Екінші жолмен қиылыстырған соң ұштарды қайта тексер: бір шек басқа шарттан келуі мүмкін.'],
  'exponential-inequality-systems':['Если первое условие требует ждать дольше, а второе — закончить раньше, сравни полученные границы. Нижняя больше верхней означает невозможность выполнить оба условия. Равные границы могут дать единственный момент. Только после этого решай, разрешён ли этот момент формулировкой и единицами времени.','Бірінші шарт ұзағырақ күтуді, екіншісі ертерек аяқтауды талап етсе, шектерді салыстыр. Төменгі шек жоғарғыдан үлкен болса, екі шарт бірге орындалмайды. Тең шектер бір сәт беруі мүмкін. Кейін оның шарт пен уақыт бірлігіне сай екенін тексер.'],
  'log-inequality-systems':['Составь небольшой список всех условий на x, включая ограничения аргументов. Зачеркни лишь те, которые логически следуют из более сильных. Например, x≥3 уже обеспечивает x>1. Такая запись помогает объяснить итог, не забыть ОДЗ и показать, почему некоторые ограничения не видны в последнем ответе.','x-ке барлық шартты, соның ішінде аргумент шектеулерін тіз. Тек күштірек шарттан шығатындарын алып таста. Мысалы, x≥3 шарты x>1-ді қамтамасыз етеді. Бұл жазба қорытындыны түсіндіруге, ММО-ны ұмытпауға және кей шарт неге соңғы жауапта жоқ екенін көрсетуге көмектеседі.'],
  'space-relations':['В коробке сравни переднее нижнее горизонтальное ребро и заднее вертикальное ребро. Они не имеют общей точки и не лежат в одной плоскости, поэтому скрещиваются. Этот пример показывает, почему привычное правило плоскости «не пересекаются — значит параллельны» в пространстве неверно.','Қораптың алдыңғы төменгі көлденең қыры мен артқы тік қырын салыстыр. Ортақ нүктесі жоқ және бір жазықтықта жатпайды, сондықтан айқас. Бұл мысал жазықтықтағы «қиылыспаса, параллель» ережесінің кеңістікте неге жарамайтынын көрсетеді.'],
  sections:['Проследи каждую сторону сечения по поверхности тела и назови грань, на которой она лежит. Если отрезок проходит через внутренность тела между двумя разными гранями, он может быть диагональю сечения, но не его стороной. Не путай вспомогательные линии с внешним контуром.','Қиманың әр қабырғасын дене бетімен бақылап, жатқан жағын ата. Кесінді екі басқа жақ арасымен дененің ішінен өтсе, ол қима диагоналі болуы мүмкін, бірақ қабырғасы емес. Көмекші сызықтарды сыртқы контурмен шатастырма.'],
  prisms:['Для одного и того же основания мысленно увеличь высоту призмы вдвое. Объём и боковая площадь прямой призмы удвоятся, а площади оснований останутся прежними. Поэтому полная поверхность обычно не удваивается. Этот тест помогает различить формулы и увидеть, что именно меняется при растяжении.','Бір табанды призманың биіктігін ойша екі еселе. Тік призма көлемі мен бүйір ауданы екі еселенеді, табан аудандары өзгермейді. Сондықтан толық бет әдетте екі еселенбейді. Бұл тексеру формулаларды ажыратып, созғанда не өзгеретінін көрсетеді.'],
  pyramids:['Отметь на рисунке основание высоты. У правильной пирамиды это центр правильного многоугольника, но у произвольной пирамиды точка может лежать в другом месте и даже вне основания. Формула объёма остаётся верной с перпендикулярной высотой, тогда как симметричные формулы боковой поверхности требуют правильности.','Суретте биіктік табанын белгіле. Дұрыс пирамидада ол дұрыс көпбұрыш центрі, ал жалпы пирамидада басқа орында, тіпті табан сыртында жатуы мүмкін. Перпендикуляр биіктікпен көлем формуласы сақталады, симметриялық бүйір бет формулалары дұрыстықты талап етеді.'],
  cylinders:['Если высота удвоена при прежнем радиусе, объём и боковая поверхность удваиваются. Если удвоен радиус при прежней высоте, объём увеличивается вчетверо, боковая площадь — вдвое. Сравнение этих двух изменений показывает, почему нельзя одной пропорцией оценивать все характеристики банки одновременно.','Радиус сақталып, биіктік екі еселенсе, көлем мен бүйір бет екі еселенеді. Биіктік сақталып, радиус екі еселенсе, көлем төрт, бүйір аудан екі есе артады. Бұл салыстыру банкі сипаттамаларының бәрін бір пропорциямен бағалауға болмайтынын көрсетеді.'],
  cones:['Проверь, что найденная образующая длиннее высоты и радиуса: она является гипотенузой. Если получилась короче, в Пифагоре, вероятно, использовано вычитание вместо сложения. Для полого колпака объём пустоты и площадь материала описывают разные стороны предмета и требуют разных формул.','Жасаушының биіктік пен радиустан ұзын екенін тексер: ол гипотенуза. Қысқа шықса, Пифагорда қосу орнына азайту қолданылған болуы мүмкін. Қуыс қалпақтың ішкі көлемі мен материал ауданы заттың әртүрлі сипаттамалары, формулалары да бөлек.'],
  spheres:['Если требуется сечение, нарисуй треугольник из радиуса шара, расстояния до плоскости и радиуса сечения. Прямой угол находится у центра круга сечения. Чем дальше плоскость от центра шара, тем меньше круг. При расстоянии больше радиуса пересечения вообще не существует.','Қима қажет болса, шар радиусы, жазықтыққа қашықтық және қима радиусынан үшбұрыш сал. Тік бұрыш қима дөңгелегі центрінде. Жазықтық шар центрінен алыстаған сайын дөңгелек кішірейеді. Қашықтық радиустан үлкен болса, қиылысу жоқ.'],
  'plane-transformations':['Возьми две точки фигуры и сравни расстояние между ними до и после движения: оно должно сохраниться. При гомотетии оно меняется в |k| раз. Эта проверка обнаруживает ошибку координат, даже если изображение выглядит похожим. Для сложной фигуры полезно проверить несколько характерных пар.','Фигураның екі нүктесін алып, қозғалысқа дейінгі және кейінгі арақашықтығын салыстыр: сақталуы тиіс. Гомотетияда |k| есе өзгереді. Кескін ұқсас көрінсе де, бұл координата қатесін табады. Күрделі фигурада бірнеше сипаттық жұпты тексер.'],
  'space-distance':['Если точка лежит в плоскости, числитель формулы расстояния равен нулю. Если все коэффициенты уравнения плоскости умножены на одно ненулевое число, расстояние не меняется: модуль числителя и знаменатель масштабируются одинаково. Это подтверждает, что формула описывает геометрию, а не выбранную запись уравнения.','Нүкте жазықтықта жатса, қашықтық формуласының алымы нөл. Жазықтық теңдеуінің барлық коэффициентін бір нөлдік емес санға көбейтсе, қашықтық өзгермейді: алым модулі мен бөлім бірдей масштабталады. Демек формула жазылу тәсілін емес, геометрияны сипаттайды.'],
  'space-transformations':['Проверь точку на оси вращения: при повороте вокруг Oz точка (0;0;z) остаётся на месте. Точка вне оси сохраняет высоту и расстояние до оси. Если алгоритм меняет эти величины, это уже не указанный поворот. Для переноса неизменны расстояния между всеми парами точек.','Бұрылу осіндегі нүктені тексер: Oz бойымен бұрғанда (0;0;z) өзгермейді. Осьтен тыс нүкте биіктік пен оське қашықтықты сақтайды. Алгоритм оларды өзгертсе, берілген бұрылу емес. Көшіруде барлық нүкте жұптарының арақашықтықтары сақталады.'],
};
for (const [id,body] of Object.entries(understandingChecks)) {
  advancedEnrichment[id].details.push({title:b('Проверь, что ты понял','Түсінгеніңді тексер'),body:b(...body)});
}
